const homeworkSubjectGroups = computed(() => {
  const groups=new Map()
  const add=(item,bucket)=>{
    const subject=String(item.subject||'').trim().replace(/\s+/g,' ')||'Без предмета'
    const key=subject.normalize('NFKC').toLocaleLowerCase('ru')
    if(!groups.has(key))groups.set(key,{key,subject,planned:[],backlog:[],firstDueDate:item.dueDate||'9999-12-31'})
    const group=groups.get(key);group[bucket].push(item)
    if(item.dueDate&&item.dueDate<group.firstDueDate)group.firstDueDate=item.dueDate
  }
  plannedHomework.value.forEach(item=>add(item,'planned'))
  homeworkBacklog.value.forEach(item=>add(item,'backlog'))
  return [...groups.values()].sort((a,b)=>a.firstDueDate.localeCompare(b.firstDueDate)||a.subject.localeCompare(b.subject,'ru'))
})
