function sortTask(a,b){ return ((a.startTime||'99:99')+(a.order||0)).localeCompare((b.startTime||'99:99')+(b.order||0)) }
function isValidDayKey(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(parseISO(value).getTime())}
function isOverdueTask(task){return !task.done&&isValidDayKey(task.date)&&task.date<todayKey.value&&!['someday','waiting','cancelled','archived'].includes(task.status)}
