async function moveProjectOneStep(project,direction){const siblings=projectSiblings(project.parentProjectId),index=siblings.findIndex(item=>item.id===project.id),next=index+direction;if(index<0||next<0||next>=siblings.length)return;[siblings[index],siblings[next]]=[siblings[next],siblings[index]];await saveProjectOrder(siblings);flash('Порядок проектов изменён');syncSoon()}
async function dropProjectOn(target){const source=store.projects.value.find(project=>project.id===dragProjectId.value);if(!source||!target||source.id===target.id){endProjectDrag();return}if(projectIdsUnder(source.id).includes(target.id)){flash('Нельзя переместить проект внутрь собственного подпроекта');endProjectDrag();return}const sourceParent=source.parentProjectId||null,targetParent=target.parentProjectId||null;if(sourceParent===targetParent){const siblings=projectSiblings(sourceParent,source.id),targetIndex=siblings.findIndex(project=>project.id===target.id);siblings.splice(Math.max(0,targetIndex),0,source);await saveProjectOrder(siblings);flash(`Проект «${source.title}» перемещён перед «${target.title}»`)}else{await saveProjectOrder(projectSiblings(sourceParent,source.id));const targetChildren=projectSiblings(target.id);await store.save({...source,parentProjectId:target.id,order:targetChildren.length+1});flash(`Проект «${source.title}» перемещён в «${target.title}»`)}syncSoon();endProjectDrag()}
