function chainEndTime(chain){return minToTime(timeToMin(chain.startTime||'00:00')+tasksForChain(chain.id).reduce((sum,task)=>sum+(Number(task.duration)||0),0))}
async function reflowChain(chainId,startTime=null){const chain=store.chains.value.find(item=>item.id===chainId);if(!chain)return;let minute=timeToMin(startTime||chain.startTime||'09:00');if(startTime&&startTime!==chain.startTime)await store.save({...chain,startTime});for(const task of tasksForChain(chainId)){await store.save({...task,date:chain.date,startTime:minToTime(minute)});minute+=Number(task.duration)||0}return minute}
