async function toggleTask(task){
  const done=!task.done
  await store.save({...task,done,status:done?'completed':(task.status==='completed'?'planned':task.status||'planned'),completedAt:done?new Date().toISOString():null})
  if(task.parentTaskId&&task.sourceSubtaskId){const parent=store.tasks.value.find(item=>item.id===task.parentTaskId);if(parent)await store.save({...parent,subtasks:(parent.subtasks||[]).map(subtask=>subtask.id===task.sourceSubtaskId?{...subtask,done}:subtask)})}
