async function saveHomework(){
  if(homeworkSaving.value)return
  homeworkError.value=''
  const title=String(editingHomework.value?.title||'').trim()
  if(!title){homeworkError.value='Напиши, что именно нужно сделать';return}
  if(!editingHomework.value?.dueDate){homeworkError.value='Выбери дату, к которой нужно выполнить задание';return}
  homeworkSaving.value=true
  try{
    const record={...JSON.parse(JSON.stringify(editingHomework.value)),title,notes:String(editingHomework.value.notes||'').trim()}
    const saved=record.id?await store.save(record):await store.add(record)
    if(!saved?.id)throw new Error('Запись не была создана')
    closeHomework()
    flash('Домашнее задание сохранено');syncSoon()
  }catch(error){
    console.error('Failed to save homework',error)
    homeworkError.value='Не удалось сохранить. Данные не потеряны — попробуй ещё раз.'
  }finally{homeworkSaving.value=false}
}
async function toggleHomework(item){
  if(item.sourceTaskId){const task=store.tasks.value.find(entry=>entry.id===item.sourceTaskId);if(task)await toggleTask(task);return}
  const done=!item.done
  const dates=item.plannedDates||[]
  const plannedDates=done&&!dates.includes(selectedDate.value)?[...dates,selectedDate.value]:dates
  await store.save({...item,done,plannedDates,completedAt:done?new Date().toISOString():null})
  flash(done?'Домашнее задание выполнено':'Задание возвращено');syncSoon()
}
