  const completedSets=sessionCompletedSets(editingSession.value)
  const saved=await store.save({...editingSession.value,completedSets,editedAt:new Date().toISOString()})
  selectedSession.value=saved;editingSession.value=null;historyEditing.value=false;historyOpen.value=true
  flash('Тренировка исправлена, статистика обновлена');syncSoon()
}
async function removeSession(session){if(!confirm('Удалить запись тренировки?'))return;await store.remove(session.id);if(selectedSession.value?.id===session.id)historyOpen.value=false;flash('Запись тренировки удалена');syncSoon()}
function statMax(){return Math.max(1,...exerciseStats.value.map(s=>selectedExerciseStat.value==='all'?s.volume:s.best))}
function statPoints(){const arr=exerciseStats.value.slice(-12);if(!arr.length)return '';return arr.map((s,i)=>`${arr.length===1?50:i/(arr.length-1)*100},${92-(selectedExerciseStat.value==='all'?s.volume:s.best)/statMax()*82}`).join(' ')}
function openTimelineItem(item){if(item.type==='task')openTask(item.source);if(item.type==='homework')openHomework({id:item.source.lessonId,subject:item.source.subject,kind:item.source.lessonKind,room:item.source.room},item.source.dueDate,item.source);if(item.type==='habit')startRitualTimer(item.source)}
function timelineForHour(hour){return timelineTasks.value.filter(item=>Math.floor(item.start/60)===hour)}
function isHourExpanded(hour){return expandedTimelineGroups.value.includes(hour)}
function toggleTimelineHour(hour){expandedTimelineGroups.value=isHourExpanded(hour)?expandedTimelineGroups.value.filter(value=>value!==hour):[...expandedTimelineGroups.value,hour]}
function timelineItemStyle(item,index,hour){if(isHourExpanded(hour))return{left:'50px',right:'10px',width:'auto',top:`${8+index*58}px`};const laneWidth=100/item.lanes;return{left:`calc(50px + ${item.lane*laneWidth}% - ${item.lane*60/item.lanes}px)`,width:`calc(${laneWidth}% - ${60/item.lanes+4}px)`,top:'8px'}}

const quick = reactive({title:'',date:store.today(),startTime:'09:00',template:'focus',workoutId:'',steps:[]})
const templates = {
 focus:{title:'Глубокая работа',icon:'briefcase',color:'#8b5cf6',steps:[['Приготовить чай и выпить витамины','prepare',10],['Определить результат блока','prepare',5],['Фокус без отвлечений','action',90],['Записать итог и следующий шаг','finish',10]]},
 workout:{title:'Тренировка',icon:'dumbbell',color:'#22c55e',steps:[['Свекольный порошок + креатин','prepare',5],['Разминка и мобилизация','prepare',10],['Основная тренировка','action',75],['Заминка и запись результатов','finish',10]]},
 custom:{title:'Новая цепочка',icon:'activity',color:'#06b6d4',steps:[['Подготовка','prepare',10],['Главное действие','action',45],['Зафиксировать результат','finish',5]]}
}
function chooseTemplate(type){const t=templates[type];quick.template=type;quick.title=t.title;quick.steps=t.steps.map(([title,stage,duration])=>({id:uid(),title,stage,duration}));if(type==='workout'){quick.workoutId=store.workouts.value[0]?.id||'';chooseWorkoutPreset()}}
function chooseWorkoutPreset(){const workout=store.workouts.value.find(w=>w.id===quick.workoutId);if(!workout)return;quick.title=`Тренировка · ${workout.title}`;const action=quick.steps.find(s=>s.stage==='action');if(action)action.title=workout.title}
function openQuick(){quick.date=selectedDate.value;quick.startTime='09:00';chooseTemplate('focus');quickOpen.value=true}
function addQuickStep(){quick.steps.push({id:uid(),title:'',stage:'action',duration:15})}
async function saveChain(){if(!quick.title.trim())return;const t=templates[quick.template];const chainId=uid();const timed=computeChainTimes(quick.steps,quick.startTime);await store.save({id:chainId,type:'chain',title:quick.title,date:quick.date,startTime:quick.startTime,icon:t.icon,color:quick.template==='workout'?(store.workouts.value.find(w=>w.id===quick.workoutId)?.color||t.color):t.color,workoutId:quick.template==='workout'?quick.workoutId:null,order:Date.now()});for(let i=0;i<timed.length;i++){const s=timed[i];if(!s.title.trim())continue;await store.save({id:uid(),type:'task',chainId,title:s.title,stage:s.stage,date:quick.date,startTime:s.startTime,duration:+s.duration||0,priority:s.stage==='action'?'high':'normal',done:false,order:i+1,recurrence:'none',subtasks:[],dependsOn:[]})}quickOpen.value=false;selectedDate.value=quick.date;view.value='today';flash('Цепочка добавлена в день');syncSoon()}
function timeToMin(v){const [h,m]=(v||'00:00').split(':').map(Number);return h*60+m}function minToTime(v){return `${String(Math.floor(v/60)%24).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`}

function openWorkout(w){
  if(!w){flash('Эта программа больше не существует');return}
  selectedWorkout.value=JSON.parse(JSON.stringify(w))
  selectedWorkout.value.sessionNote=''
  selectedWorkout.value.sessionStartedAt=new Date().toISOString()
  const previous=store.state.records.filter(r=>r.type==='session'&&r.workoutId===w.id).sort((a,b)=>b.finishedAt.localeCompare(a.finishedAt))[0]
  selectedWorkout.value.log=w.exercises.map(ex=>{
    const old=previous?.log?.find(item=>item.exerciseId===ex.id)?.sets||[]
    return {exerciseId:ex.id,sets:Array.from({length:ex.sets},(_,i)=>({id:uid(),weight:'',reps:'',rir:'',done:false,previous:old[i]?.weight?`${old[i].weight} кг × ${old[i].reps}`:''}))}
  })
  workoutOpen.value=true
}
function newWorkoutSet(){return {id:uid(),weight:'',reps:'',rir:'',done:false,previous:''}}
function addWorkoutSet(exerciseIndex){selectedWorkout.value.log[exerciseIndex].sets.push(newWorkoutSet());navigator.vibrate?.(15)}
function removeWorkoutSet(exerciseIndex,setIndex){
  const sets=selectedWorkout.value.log[exerciseIndex].sets
  if(sets.length<=1){flash('В упражнении должен остаться хотя бы один подход');return}
  const set=sets[setIndex]
  if((set.done||set.weight||set.reps)&&!confirm('Убрать заполненный подход?'))return
  sets.splice(setIndex,1)
}
function toggleSet(set, rest=90){set.done=!set.done;if(set.done){startTimer(rest);navigator.vibrate?.(30)}}
async function finishWorkout(){
  if(workoutSaving.value)return
  workoutSaving.value=true
  try{
    const completedSets=selectedWorkout.value.log.reduce((count,item)=>count+item.sets.filter(set=>set.done).length,0)
    await store.add({type:'session',workoutId:selectedWorkout.value.id,date:store.today(),startedAt:selectedWorkout.value.sessionStartedAt,finishedAt:new Date().toISOString(),note:selectedWorkout.value.sessionNote||'',completedSets,workoutSnapshot:{title:selectedWorkout.value.title,day:selectedWorkout.value.day,exercises:selectedWorkout.value.exercises.map(ex=>({id:ex.id,title:ex.title,reps:ex.reps}))},log:selectedWorkout.value.log})
    workoutOpen.value=false;localStorage.removeItem('momentum.workoutDraft');stopTimer();timerSeconds.value=0
    workoutTab.value='history'
    flash(`Тренировка записана · ${completedSets} подходов`);syncSoon()
  }catch(error){
    console.error('Failed to save workout',error)
    flash('Не удалось сохранить тренировку. Данные остались на экране — попробуй ещё раз.')
  }finally{workoutSaving.value=false}
}
function startTimer(seconds){prepareTimerSound();timerSeconds.value=seconds;timerRunning.value=true;clearInterval(timerInterval);timerInterval=setInterval(()=>{if(timerSeconds.value>0)timerSeconds.value--;else{stopTimer();playTimerSound();navigator.vibrate?.([200,100,200]);flash('Отдых окончен')}} ,1000)}
function stopTimer(){clearInterval(timerInterval);timerRunning.value=false}
function timerText(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}

const auth = reactive({email:'',password:'',url:cloud.url,key:cloud.key,mode:'signin',busy:false})
async function saveCloudConfig(){try{await configureCloud(auth.url,auth.key);flash('Подключение сохранено');cloudOpen.value=true}catch(e){flash(e.message)}}
async function submitAuth(){auth.busy=true;try{if(auth.mode==='signin'){await signIn(auth.email,auth.password);flash('Данные синхронизированы')}else{await signUp(auth.email,auth.password);flash('Проверьте почту для подтверждения')} }catch(e){flash(e.message)}finally{auth.busy=false}}
async function doSync(){await syncNow();flash(cloud.error||'Синхронизация завершена')}
async function exportData(){const records=await store.allWithDeleted();const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`momentum-backup-${store.today()}.json`;a.click();URL.revokeObjectURL(a.href);flash('Резервная копия скачана')}
function importData(event){const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.records)||data.version!==1)throw new Error('Неверный формат');await exportData();await store.replaceAll(data.records.map(r=>({...r,dirty:1})));flash('Данные восстановлены');syncSoon()}catch(e){flash('Не удалось прочитать резервную копию')}};reader.readAsText(file)}
async function resetData(){if(!confirm('Удалить локальные данные и начать заново?'))return;await store.reset();location.reload()}
let syncTimer;function syncSoon(){if(!cloud.connected)return;clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,1200)}
function formatSync(){if(!cloud.lastSync)return 'ещё не было';return format(new Date(cloud.lastSync),'HH:mm, d MMM',{locale:ru})}
function toggleSidebar(){sidebarCollapsed.value=!sidebarCollapsed.value;localStorage.setItem('momentum.sidebarCollapsed',String(sidebarCollapsed.value))}
function setView(id){view.value=id;if(id==='today')selectedDate.value=store.today()}

watch(selectedWorkout, value=>{if(workoutOpen.value&&value)localStorage.setItem('momentum.workoutDraft',JSON.stringify(value))},{deep:true})
watch(editingHomework, value=>{if(homeworkOpen.value&&value)localStorage.setItem('momentum.homeworkDraft',JSON.stringify(value))},{deep:true})
watch(editingChainTemplate,value=>{if(chainTemplateOpen.value&&value){schedulePreview.value=null;localStorage.setItem('momentum.chainBuilderDraft',JSON.stringify(value));chainDraftAvailable.value=true}},{deep:true})
function restoreChainDraft(){const draft=JSON.parse(localStorage.getItem('momentum.chainBuilderDraft')||'null');if(!draft)return;editingChainTemplate.value=draft;chainTemplateOpen.value=true}
function discardChainDraft(){localStorage.removeItem('momentum.chainBuilderDraft');chainDraftAvailable.value=false}

onMounted(async()=>{applyTheme(currentTheme.value);await store.init();await initCloud();await loadBackups();chainDraftAvailable.value=Boolean(localStorage.getItem('momentum.chainBuilderDraft'));
  const focusDraft=JSON.parse(localStorage.getItem('momentum.activeFocus')||'null');if(focusDraft){const draftTask=store.tasks.value.find(task=>task.id===focusDraft.taskId),focusDate=draftTask?.date||selectedDate.value,record=store.state.records.find(item=>item.type==='dayFocus'&&item.date===focusDate),validTask=draftTask&&!draftTask.done&&!['someday','waiting','cancelled','archived'].includes(draftTask.status);if(validTask&&(!record||record.taskId===draftTask.id)){const savedAt=Number(focusDraft.savedAt)||Date.now(),elapsed=focusDraft.running?Math.max(0,Math.floor((Date.now()-savedAt)/1000)):0;focusTaskId.value=draftTask.id;focusSeconds.value=Math.max(0,(Number(focusDraft.seconds)||0)-elapsed);focusStartedAt.value=focusDraft.startedAt;focusDistractions.value=focusDraft.distractions||[];focusMinimized.value=Boolean(focusDraft.minimized);focusOpen.value=!focusMinimized.value;if(!record)await store.add({type:'dayFocus',date:focusDate,taskId:draftTask.id})}else{focusTaskId.value=null;focusMinimized.value=false;localStorage.removeItem('momentum.activeFocus')}}
  const workoutDraft=JSON.parse(localStorage.getItem('momentum.workoutDraft')||'null');if(workoutDraft){selectedWorkout.value=workoutDraft;workoutOpen.value=true;flash('Незавершённая тренировка восстановлена')}
  const homeworkDraft=JSON.parse(localStorage.getItem('momentum.homeworkDraft')||'null');if(homeworkDraft){editingHomework.value=homeworkDraft;homeworkOpen.value=true}
  const hour=new Date().getHours();const reviewDue=hour>=19?!todayReview.value?.eveningAt:!todayReview.value?.morningAt;if(selectedDate.value===todayKey.value&&reviewDue&&!workoutDraft&&!homeworkDraft)setTimeout(()=>openReview(hour>=19?'evening':'morning'),500)
  checkNotifications();notificationInterval=setInterval(checkNotifications,60000)
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncNow()});window.addEventListener('momentum:update-ready',()=>{updateAvailable.value=true;toast.value='Доступна новая версия'});window.addEventListener('momentum:offline-ready',()=>flash('Приложение готово к работе без сети'))})
onBeforeUnmount(()=>{clearInterval(timerInterval);clearInterval(focusInterval);clearInterval(ritualInterval);clearInterval(notificationInterval);clearTimeout(syncTimer)})
</script>

<template>
  <div class="app-shell" :class="{'has-focus-mini':focusMinimized&&focusedTask,'has-focus-mini-ritual':focusMinimized&&focusedTask&&ritualTimer.habit,'sidebar-collapsed':sidebarCollapsed}">
    <aside class="sidebar">
      <div class="sidebar-brand-row">
        <div class="brand" :title="sidebarCollapsed?'Momentum':null"><span class="brand-mark"><Check :size="19" stroke-width="3"/></span><span class="brand-label">Momentum</span></div>
        <button class="sidebar-toggle" type="button" :aria-label="sidebarCollapsed?'Развернуть боковую панель':'Свернуть боковую панель'" :title="sidebarCollapsed?'Развернуть панель':'Свернуть панель'" :aria-pressed="sidebarCollapsed" aria-controls="primary-sidebar-nav" @click="toggleSidebar"><component :is="sidebarCollapsed?ChevronRight:ChevronLeft" :size="17"/></button>
      </div>
      <nav id="primary-sidebar-nav" class="nav">
        <button v-for="item in nav" :key="item.id" class="nav-btn" :class="{active:view===item.id}" :aria-label="item.label" :title="sidebarCollapsed?item.label:null" @click="setView(item.id)"><component :is="item.icon" :size="18"/><span class="nav-label">{{item.label}}</span></button>
      </nav>
      <div class="sidebar-bottom">
        <button class="nav-btn" style="width:100%" aria-label="Облако" :title="sidebarCollapsed?'Облако':null" @click="cloudOpen=true"><Cloud :size="18"/><span class="nav-label">Облако</span></button>
        <div class="sync-pill" role="status" :aria-label="sidebarSyncLabel" :title="sidebarSyncLabel"><span class="sync-dot" :class="{ok:cloud.connected,spin:cloud.syncing}"></span><span class="sync-label">{{sidebarSyncLabel}}</span></div>
      </div>
    </aside>

    <main class="main">
      <div class="page">
        <header class="topbar">
          <div><div class="eyebrow">{{ view==='today' ? format(new Date(),'EEEE, d MMMM',{locale:ru}) : 'Momentum' }}</div><h1 class="page-title">{{view==='today'?dateTitle:pageTitle}}</h1></div>
          <div class="header-actions">
            <button v-if="view==='today'" type="button" class="icon-btn day-nav-btn" aria-label="Предыдущий день" @click="changeDay(-1)"><ChevronLeft :size="17"/></button><label v-if="view==='today'" class="date-picker-btn" aria-label="Выбрать дату"><CalendarDays :size="17"/><input v-model="selectedDate" type="date"/></label><button v-if="view==='today'" type="button" class="icon-btn day-nav-btn" aria-label="Следующий день" @click="changeDay(1)"><ChevronRight :size="17"/></button>
            <button class="ghost-btn inbox-trigger" @click="inboxOpen=true"><Inbox :size="16"/><span>Входящие</span><b v-if="store.inbox.value.length">{{store.inbox.value.length}}</b></button>
            <button class="ghost-btn" @click="cloudOpen=true"><component :is="cloud.connected?Cloud:CloudOff" :size="16"/><span>{{cloud.connected?'В облаке':'Подключить'}}</span></button>
          </div>
        </header>

        <template v-if="!store.state.ready"><div class="card card-pad skeleton" style="height:180px"></div></template>

        <template v-else-if="view==='today'">
          <div v-if="overdueTasks.length && selectedDate===todayKey" class="overdue-banner card" role="alert"><div><strong>{{overdueTasks.length}} {{pluralize(overdueTasks.length,['незавершённое действие','незавершённых действия','незавершённых действий'])}}</strong><div class="section-meta">Разбери хвост осознанно — ничего не переносится без твоего решения.</div></div><div class="row" style="flex:0"><button type="button" class="ghost-btn" @click="openOverdueTasks">Разобрать</button><button class="primary-btn" @click="openTransfer()">На сегодня</button></div></div>
          <div class="grid-dashboard">
            <section>
              <div class="card hero-card">
                <div class="eyebrow">Фокус дня</div>
                <h2 style="font-size:21px;margin:7px 0 5px">{{activeTask?.title || 'День свободен — выбери главное'}}</h2>
                <div style="font-size:11px;color:#858894">{{activeTask ? `${activeTask.startTime||'Без времени'} · ${activeTask.duration||0} мин · ${stageLabel(activeTask.stage)}` : 'Добавь цепочку действий, и план станет ясным'}}</div><span v-if="taskProjectInfo(activeTask)" class="task-project-badge focus-project-badge" :style="{'--task-project-color':taskProjectInfo(activeTask).color}" :title="`Проект: ${taskProjectInfo(activeTask).name}`"><FolderKanban :size="11" aria-hidden="true"/><span>{{taskProjectInfo(activeTask).name}}</span></span>
                <div class="progress-row"><div class="progress-track"><div class="progress-fill" :style="{width:progress+'%'}"></div></div><div class="progress-label">{{progress}}%</div></div>
                <div v-if="activeTask" class="focus-controls"><button type="button" class="focus-change" aria-haspopup="dialog" @click.stop="openFocusPicker"><SlidersHorizontal :size="14"/> Сменить фокус</button><button class="focus-launch" @click="launchFocusMode"><Maximize2 :size="15"/> Режим «Сейчас»</button></div>
              </div>

              <div class="day-command card"><button @click="openReview('morning')"><Sunrise :size="18"/><span><strong>{{todayReview?.morningAt?'Утренний ритуал завершён':'Начать утренний ритуал'}}</strong><small>Шаги больших задач и благодарность</small></span></button><div class="day-load" :class="{overload:capacity.overload}"><Gauge :size="18"/><span><strong>{{Math.round(capacity.planned/60*10)/10}} / {{Math.round(capacity.available/60*10)/10}} ч</strong><small>{{capacity.overload?'Перегрузка '+capacity.overload+' мин':'Резерв '+capacity.free+' мин'}}</small></span></div><button @click="openReview('evening')"><Moon :size="18"/><span><strong>{{todayReview?.eveningAt?'Вечерний ритуал завершён':'Начать вечерний ритуал'}}</strong><small>Урок, исправление и новое поведение</small></span></button></div>
              <div v-if="capacity.overload" class="overload-advice card"><AlertCircle :size="17"/><div><strong>План перегружен на {{capacity.overload}} мин</strong><span>Перенеси {{dayTasks.filter(task=>!task.done&&task.priority!=='high').slice(-2).map(task=>task.title).join(' или ')||'одну необязательную задачу'}} либо сократи подготовки. Оставь минимум 30 минут резерва.</span></div><button @click="view='tasks'">Исправить план</button></div><div v-if="dayChains.length" class="card today-chain-overview"><div><strong>Цепочки на {{selectedDate===todayKey?'сегодня':format(parseISO(selectedDate),'d MMMM',{locale:ru})}}</strong><span>{{dayChains.length}} цепочек · находятся ниже в подробном плане</span></div><button v-for="chain in dayChains" :key="chain.id" :style="{'--chain':chain.color}" @click="scrollToDayChain(chain.id)"><i></i><span><strong>{{chain.title}}</strong><small>{{chain.startTime}} · {{chainProgress(chain.id)}} готово</small></span><ChevronDown :size="14"/></button></div>
              <div v-if="suggestedForWindows.length" class="smart-windows"><div class="section-meta">Подходящие задачи в свободные окна</div><div v-for="window in suggestedForWindows.slice(0,2)" :key="window.start" class="smart-window"><span>{{fromMinutes(window.start)}}–{{fromMinutes(window.end)}} · {{window.duration}} мин</span><button v-for="task in window.tasks.slice(0,2)" :key="task.id" :title="taskProjectInfo(task)?`Проект: ${taskProjectInfo(task).name}`:task.title" @click="scheduleTaskInWindow(task,window)"><span>{{task.title}}</span><small v-if="taskProjectInfo(task)">{{taskProjectInfo(task).name}}</small></button></div></div>
              <div v-if="plannedHomework.length || homeworkBacklog.length || nextDayClasses.length" class="section-head"><div><h2>Домашнее задание</h2><div class="section-meta">Выбери задания, которые собираешься сделать в этот день</div></div></div><div v-if="plannedHomework.length || homeworkBacklog.length || nextDayClasses.length" class="homework-today card"><div class="homework-plan-head"><div><strong>ДЗ на {{selectedDate===todayKey?'сегодня':format(parseISO(selectedDate),'d MMMM',{locale:ru})}}</strong><span>{{visibleHomeworkDone}} из {{visibleHomeworkTotal}} выполнено · прогресс считается по заданиям, которые видны в списке</span></div><b>{{plannedHomeworkProgress}}%</b></div><div class="homework-progress-track"><div :style="{width:plannedHomeworkProgress+'%'}"></div></div><div v-if="!plannedHomework.length" class="homework-plan-empty">Отметь «В план», чтобы выделить приоритетные задания. Общий прогресс учитывает все ДЗ, видимые ниже.</div><div v-for="group in homeworkSubjectGroups" :key="group.key" class="homework-subject-group"><div class="homework-subject-heading"><strong>{{group.subject}}</strong><span class="homework-subject-counts"><span v-if="group.planned.length">{{group.planned.length}} в плане</span><span v-if="group.backlog.length">{{group.backlog.length}} ещё</span></span></div><div v-for="item in group.planned" :key="item.id" class="homework-row with-plan planned" :class="{overdue:item.dueDate<selectedDate,done:item.done}"><button class="check" :class="{done:item.done}" @click="toggleHomework(item)"><Check v-if="item.done" :size="13"/></button><div @click="openHomework({id:item.lessonId,subject:item.subject,kind:item.lessonKind,room:item.room},item.dueDate,item)"><strong>{{item.title}}</strong><span>{{item.lessonKind||'Задание'}} · к {{format(parseISO(item.dueDate),'d MMMM',{locale:ru})}}</span></div><button class="plan-homework-btn active" :class="{completed:item.done}" @click="toggleHomeworkPlan(item)"><CheckCircle2 v-if="item.done" :size="13"/><Target v-else :size="13"/> {{item.done?'Выполнено':'В плане'}}</button><span class="homework-due">{{format(parseISO(item.dueDate),'d MMM')}}</span></div><div v-if="group.planned.length&&group.backlog.length" class="homework-backlog-label">Остальные невыполненные</div><div v-for="item in group.backlog" :key="item.id" class="homework-row with-plan" :class="{overdue:item.dueDate<selectedDate}"><button class="check" @click="toggleHomework(item)"></button><div @click="openHomework({id:item.lessonId,subject:item.subject,kind:item.lessonKind,room:item.room},item.dueDate,item)"><strong>{{item.title}}</strong><span>{{item.lessonKind||'Задание'}} · к {{format(parseISO(item.dueDate),'d MMMM',{locale:ru})}}</span></div><button class="plan-homework-btn" @click="toggleHomeworkPlan(item)"><Plus :size="13"/> В план</button><span class="homework-due">{{format(parseISO(item.dueDate),'d MMM')}}</span></div></div><button v-for="lesson in nextDayHomeworkPrompts" :key="lesson.id" class="homework-prompt" @click="openHomework(lesson,nextDayKey)"><Plus :size="14"/><span><strong>Добавить ДЗ к {{lesson.subject}}</strong><small>Ближайшая пара · {{format(parseISO(nextDayKey),'d MMM',{locale:ru})}}, {{lesson.start}}</small></span></button></div>
              <div v-if="selectedClasses.length" class="section-head"><h2>Пары</h2><button class="section-link" @click="view='study'">{{selectedAcademicWeek===1?'I':'II'}} неделя · всё расписание <ArrowRight :size="13"/></button></div><div v-if="selectedClasses.length" class="today-classes"><article v-for="lesson in selectedClasses" :key="lesson.id" class="class-mini card"><div class="class-time"><strong>{{lesson.start}}</strong><span>{{lesson.end}}</span></div><div><strong>{{lesson.subject}}</strong><span><component :is="lessonKindIcon(lesson.kind)" :size="12"/> {{lesson.kind}} · ауд. {{lesson.room}}</span></div><div class="class-actions"><span class="pair-badge">{{lesson.pair}} пара</span><button class="homework-btn" @click="openHomework(lesson,selectedDate)"><NotebookPen :size="13"/> ДЗ <b v-if="homeworkForOccurrence(lesson,selectedDate).length">{{homeworkForOccurrence(lesson,selectedDate).length}}</b></button></div></article></div>
              <div class="section-head"><h2>Цепочки действий</h2><span class="section-meta">{{dayChains.length}} потоков · {{completedCount}}/{{dayTasks.length}} действий</span></div>
              <article v-for="chain in dayChains" :id="`day-chain-${chain.id}`" :key="chain.id" class="card chain" :class="{'chain-moving':longPressChainId===chain.id}" :style="{'--chain':chain.color}" :data-chain-drop="chain.id" @dragover.prevent @drop="dropOnPlanChain(chain.id)">
                <div class="chain-head"><div class="chain-icon chain-drag-icon" draggable="true" @dragstart="chainDragStart(chain,$event)" @dragend="cancelChainLongPress" @pointerdown.stop="beginChainLongPress(chain)"><component :is="iconMap[chain.icon]||Activity" :size="18"/></div><div><div class="chain-title">{{chain.title}}</div><div class="chain-sub">{{chain.startTime}}–{{chainEndTime(chain)}} · {{chainProgress(chain.id)}} готово</div></div><button v-if="chain.workoutId" class="mini-btn" @click="openWorkout(store.workouts.value.find(w=>w.id===chain.workoutId))"><Play :size="12"/> Начать</button><button class="chain-more" :aria-label="`Настроить ${chain.title}`" @click="openChain(chain)"><MoreHorizontal :size="18"/></button></div>
                <div><div v-for="task in tasksForChain(chain.id)" :key="task.id" class="task-row" :class="{blocked:blocked(task)}" draggable="true" @dragstart="dragStart(task)" @dragover.prevent @drop.stop="dropOnTask(task)"><GripVertical class="drag-handle" :size="14"/><button class="check" :disabled="blocked(task)" :aria-label="task.done?'Вернуть действие':'Завершить действие'" :class="{done:task.done}" @click="toggleTask(task)"><Check v-if="task.done" :size="13" stroke-width="3"/><Link2 v-else-if="blocked(task)" :size="10"/></button><span class="task-time">{{task.startTime}}</span><div @click="openTask(task)" style="min-width:0;cursor:pointer"><div class="task-title" :class="{done:task.done}">{{task.title}}</div><div class="task-stage">{{blocked(task)?'Ожидает связанных действий':stageLabel(task.stage)}}<span v-if="taskProjectInfo(task)" class="task-project-badge" :style="{'--task-project-color':taskProjectInfo(task).color}" :title="`Проект: ${taskProjectInfo(task).name}`"><FolderKanban :size="10" aria-hidden="true"/><span>{{taskProjectInfo(task).name}}</span></span><button v-if="task.subtasks?.length" type="button" class="today-checklist-toggle" :aria-expanded="expandedTodayChecklists.includes(task.id)" :aria-label="`${expandedTodayChecklists.includes(task.id)?'Скрыть':'Показать'} чек-лист: ${task.title}`" @click.stop="toggleTodayChecklist(task.id)"><span>{{expandedTodayChecklists.includes(task.id)?'Скрыть':'Чек-лист'}} {{task.subtasks.filter(s=>s.done).length}}/{{task.subtasks.length}}</span><ChevronDown :size="11" aria-hidden="true"/></button></div></div><span class="duration">{{task.duration}}м</span><div v-if="task.subtasks?.length && expandedTodayChecklists.includes(task.id)" class="today-subtasks"><button v-for="sub in task.subtasks" :key="sub.id" type="button" class="today-subtask" :class="{done:sub.done}" :aria-pressed="sub.done" @click.stop="toggleSubtask(task,sub)"><span class="check" :class="{done:sub.done}" aria-hidden="true"><Check v-if="sub.done" :size="11"/></span><span>{{sub.title}}</span></button></div></div></div>
              </article>
              <div v-for="task in looseTasks" :key="task.id" class="card loose-task task-row" :class="{'long-press-active':longPressTaskId===task.id}" :draggable="!task.done" @dragstart="!task.done&&dragStart(task)" @dragend="cancelLongPress"><GripVertical v-if="!task.done" class="drag-handle" :size="14" @pointerdown.stop="beginLongPress(task)"/><button class="check" :class="{done:task.done}" @click="toggleTask(task)"><Check v-if="task.done" :size="13"/></button><span class="task-time">{{task.startTime||'—'}}</span><div @click="openTask(task)" style="cursor:pointer;min-width:0"><div class="task-title" :class="{done:task.done}">{{task.title}}</div><div class="task-stage">{{stageLabel(task.stage)}}<span v-if="taskProjectInfo(task)" class="task-project-badge" :style="{'--task-project-color':taskProjectInfo(task).color}" :title="`Проект: ${taskProjectInfo(task).name}`"><FolderKanban :size="10" aria-hidden="true"/><span>{{taskProjectInfo(task).name}}</span></span><button v-if="task.subtasks?.length" type="button" class="today-checklist-toggle" :aria-expanded="expandedTodayChecklists.includes(task.id)" :aria-label="`${expandedTodayChecklists.includes(task.id)?'Скрыть':'Показать'} чек-лист: ${task.title}`" @click.stop="toggleTodayChecklist(task.id)"><span>{{expandedTodayChecklists.includes(task.id)?'Скрыть':'Чек-лист'}} {{task.subtasks.filter(s=>s.done).length}}/{{task.subtasks.length}}</span><ChevronDown :size="11" aria-hidden="true"/></button></div><select v-if="dayChains.length&&!task.done" class="mini-chain-select today-task-chain-select" :aria-label="`Переместить «${task.title}» в цепочку`" @click.stop @change.stop="moveTaskToChainMenu(task,$event.target.value);$event.target.value=''"><option value="">В цепочку…</option><option v-for="chain in dayChains" :key="chain.id" :value="chain.id">{{chain.title}}</option></select></div><span class="duration">{{task.duration}}м</span><div v-if="task.subtasks?.length && expandedTodayChecklists.includes(task.id)" class="today-subtasks today-subtasks-loose"><button v-for="sub in task.subtasks" :key="sub.id" type="button" class="today-subtask" :class="{done:sub.done}" :aria-pressed="sub.done" @click.stop="toggleSubtask(task,sub)"><span class="check" :class="{done:sub.done}" aria-hidden="true"><Check v-if="sub.done" :size="11"/></span><span>{{sub.title}}</span></button></div></div>
              <button class="quick-add" @click="view='tasks'"><Plus :size="15"/> Собрать цепочку во вкладке «План»</button>
            </section>

            <aside class="side-column">
              <div class="card side-card"><div class="section-head" style="margin:0 0 8px"><h3>Ритуалы сегодня</h3><span class="section-meta">{{trackableHabits.filter(h=>habitValue(h)>=h.target).length}}/{{trackableHabits.length}}</span></div>
                <div v-for="habit in trackableHabits" :key="habit.id" class="habit"><div class="habit-icon" :style="{color:habit.color,background:habit.color+'18'}"><component :is="iconMap[habit.icon]||Activity" :size="17"/></div><div><div class="habit-title">{{habit.title}}</div><div class="habit-sub">{{habit.subtitle}} <span v-if="habitStreak(habit)">· 🔥 {{habitStreak(habit)}}</span></div></div><button v-if="habit.timerMinutes" class="habit-timer-btn" :aria-label="`Запустить таймер ${habit.title}`" @click="startRitualTimer(habit)"><Timer :size="14"/>{{habit.timerMinutes}}</button><button class="habit-toggle" :class="{done:habitValue(habit)>=habit.target}" @click="toggleHabit(habit)"><Check v-if="habitValue(habit)>=habit.target" :size="14"/><span v-else-if="habit.target>1" style="font-size:9px">{{habitValue(habit)}}/{{habit.target}}</span></button></div>
              </div>
              <div v-if="intentions.length" class="card side-card intention-card"><div class="section-head" style="margin:0 0 8px"><h3>Намерения дня</h3><span class="section-meta">Помнить, не отмечать</span></div><div v-for="item in intentions" :key="item.id" class="intention-row"><span :style="{background:item.color}"></span><div><strong>{{item.title}}</strong><small>{{item.subtitle}}</small></div></div></div>
            </aside>
          </div>
        </template>

        <template v-else-if="view==='tasks'">
          <div class="section-head" style="margin-top:0"><div><h2>Проекты и подпроекты</h2><div class="section-meta">Например: Учёба → Предмет → задачи · перетащи проект за ручку, чтобы изменить порядок или вложить его</div></div><button class="ghost-btn" @click="openProject()"><Plus :size="15"/> Проект</button></div><div class="project-strip"><div v-for="entry in projectTreeEntries" :key="entry.project.id" class="project-card-item" :class="{'project-drop-target':projectDropTargetId===entry.project.id,'project-dragging':projectDragId===entry.project.id}" :style="{'--project':entry.project.color,'--depth':entry.depth}" :data-project-drop="entry.project.id" @dragover.prevent="setProjectDropTarget(entry.project.id)" @drop.prevent.stop="dropProjectOn(entry.project)"><button class="project-card card" :class="{'subproject-card':entry.depth}" @click="openProject(entry.project)"><span>{{isValidDayKey(entry.project.targetDate)?format(parseISO(entry.project.targetDate),'d MMM',{locale:ru}):'Без срока'}} · {{entry.depth?'Подпроект':'Проект'}}</span><strong>{{projectPath(entry.project)}}</strong><small>{{entry.project.outcome||'Добавь измеримый результат'}}</small><div><i :style="{width:projectProgress(entry.project)+'%'}"></i></div><b>{{projectProgress(entry.project)}}%</b></button><button type="button" class="project-drag-handle" draggable="true" :aria-label="`Переместить проект «${projectPath(entry.project)}». Стрелки вверх и вниз меняют порядок.`" title="Перетащить на другой проект; ↑/↓ — изменить порядок" @click.stop @pointerdown.stop="beginProjectLongPress(entry.project)" @dragstart.stop="startProjectDrag(entry.project,$event)" @dragend.stop="endProjectDrag" @keydown.up.prevent="moveProjectOneStep(entry.project,-1)" @keydown.down.prevent="moveProjectOneStep(entry.project,1)"><GripVertical :size="14"/></button></div><button v-if="!store.projects.value.length" class="project-empty card" @click="openProject()"><FolderKanban :size="20"/> Создать первый проект</button></div><div v-if="dragProjectId" class="project-root-drop" :class="{active:projectDropTargetId==='root'}" @dragover.prevent.stop="setProjectDropTarget('root')" @drop.prevent.stop="dropProjectToRoot"><FolderKanban :size="14"/> Переместить в корневые проекты</div><div v-if="deadlines.length" class="deadline-strip"><strong>Ближайшие контрольные точки</strong><button v-for="task in deadlines.slice(0,4)" :key="task.id" :title="taskProjectInfo(task)?`Проект: ${taskProjectInfo(task).name}`:task.title" @click="openTask(task)"><span>{{task.deadlineKind}}</span>{{task.title}} · {{isValidDayKey(task.date)?format(parseISO(task.date),'d MMM',{locale:ru}):'Без даты'}}<small v-if="taskProjectInfo(task)">{{taskProjectInfo(task).name}}</small></button></div>
          <div v-if="chainDraftAvailable" class="recovery-banner card"><span>Остался незавершённый конструктор цепочки</span><button class="primary-btn" @click="restoreChainDraft">Продолжить</button><button class="ghost-btn" @click="discardChainDraft">Сбросить</button></div><div v-if="deadlineRisks.length" class="deadline-risk card"><strong>Ближайшие реальные дедлайны</strong><button v-for="item in deadlineRisks.slice(0,5)" :key="item.task.id" :title="taskProjectInfo(item.task)?`Проект: ${taskProjectInfo(item.task).name}`:item.task.title" @click="openTask(item.task)"><span :class="{danger:item.days<1}">{{item.days<0?'Просрочено':item.days===0?'Сегодня':item.days+' дн.'}}</span>{{item.task.title}}<small v-if="taskProjectInfo(item.task)">{{taskProjectInfo(item.task).name}}</small></button></div><div v-if="somedayTasks.length" class="someday-box card"><div><strong>Когда-нибудь</strong><small>Не нагружает текущий день</small></div><button v-for="task in somedayTasks.slice(0,6)" :key="task.id" :title="taskProjectInfo(task)?`Проект: ${taskProjectInfo(task).name}`:task.title" @click="planSomedayTask(task)"><strong class="someday-task-name">{{task.title}}</strong><small v-if="taskProjectInfo(task)" class="someday-project-name">{{taskProjectInfo(task).name}}</small><span class="someday-task-action">На выбранный день</span></button></div>
          <div class="section-head chain-template-heading"><div><h2>Заготовки цепочек</h2><div class="section-meta">Подготовки заданы заранее, задачи выбираются отдельно для каждой цепочки и дня</div></div><button class="ghost-btn" @click="openChainTemplate()"><Plus :size="15"/> Заготовка</button></div><div class="chain-template-strip"><button v-for="template in store.chainTemplates.value" :key="template.id" class="card chain-template-card" :style="{'--chain':template.color}" @click="openChainTemplate(template)"><component :is="iconMap[template.icon]||Activity" :size="18"/><span><strong>{{template.title}}</strong><small>{{template.preparations?.length||0}} подготовок · настроить</small></span></button></div>
          <div class="section-head"><div class="input search" style="display:flex;align-items:center;gap:8px"><Search :size="15"/><input v-model="search" aria-label="Поиск действий" placeholder="Найти задачу или цепочку…" style="border:0;background:none;outline:0;width:100%;color:white"/></div><div class="row" style="flex:0"><button class="ghost-btn" @click="openTask()"><Plus :size="16"/> Задача</button></div></div>
          <div class="filter-bar"><button v-for="f in [{id:'all',t:'Все'},{id:'overdue',t:'Просрочено'},{id:'blocked',t:'Ожидают'},{id:'quick',t:'≤ 15 минут'},{id:'important',t:'Важные'},{id:'waiting',t:'Ожидание'},{id:'someday',t:'Когда-нибудь'}]" :key="f.id" class="filter-chip" :class="{active:taskFilter===f.id}" @click="taskFilter=f.id">{{f.t}}<span v-if="f.id==='overdue'&&overdueTasks.length">{{overdueTasks.length}}</span></button><select v-if="allTags.length" class="select compact" v-model="selectedTag"><option value="all">Все теги</option><option v-for="tag in allTags" :key="tag">{{tag}}</option></select></div>
          <div class="section-head plan-group-heading"><h2>{{taskFilter==='overdue'?'Просроченные цепочки':`Цепочки на ${selectedDate===todayKey?'сегодня':format(parseISO(selectedDate),'d MMMM',{locale:ru})}`}}</h2><span class="section-meta">{{taskFilter==='overdue'?'Цепочки, внутри которых остались просроченные действия':'Этот же список показывается во вкладке «Сегодня» · переноси цепочки за боковой маркер'}}</span></div><div class="plan-chain-list"><article v-for="chain in planChains" :key="chain.id" class="card plan-chain-card" :class="{expanded:isPlanChainExpanded(chain.id),'drag-target':longPressTaskId||longPressChainId,'chain-moving':longPressChainId===chain.id}" :style="{'--chain':chain.color}" :data-chain-drop="chain.id" @dragover.prevent @drop="dropOnPlanChain(chain.id)"><span class="chain-reorder-handle" draggable="true" title="Перенести цепочку" @dragstart="chainDragStart(chain,$event)" @dragend="cancelChainLongPress" @pointerdown.stop="beginChainLongPress(chain)"><GripVertical :size="15"/></span><button class="plan-chain-summary" @click="togglePlanChain(chain.id)"><div class="chain-icon"><component :is="iconMap[chain.icon]||Activity" :size="18"/></div><div><strong>{{chain.title}}</strong><small>{{chainDateLabel(chain)}} · {{chain.startTime}}–{{chainEndTime(chain)}} · {{chainProgress(chain.id)}} · {{tasksForChain(chain.id).reduce((sum,task)=>sum+(Number(task.duration)||0),0)}} мин</small></div><span>{{tasksForChain(chain.id).filter(task=>task.stage==='prepare').length}} подг. · {{tasksForChain(chain.id).filter(task=>task.stage==='action').length}} задач</span><ChevronDown :size="17"/></button><button class="chain-more plan-chain-more" @click="openChain(chain)"><MoreHorizontal :size="18"/></button><select v-if="planChains.length>1" class="chain-move-menu" aria-label="Поставить цепочку перед другой" @change="moveChainBeforeMenu(chain,$event.target.value);$event.target.value=''"><option value="">Переместить…</option><option v-for="target in planChains.filter(item=>item.id!==chain.id)" :key="target.id" :value="target.id">Перед «{{target.title}}»</option></select><div v-if="isPlanChainExpanded(chain.id)" class="plan-chain-steps"><div v-for="task in tasksForChain(chain.id)" :key="task.id" class="task-row plan-row" draggable="true" @dragstart="dragStart(task)" @dragend="cancelLongPress" @dragover.prevent @drop.stop="dropOnTask(task)"><GripVertical class="drag-handle" :size="14" @pointerdown.stop="beginLongPress(task)"/><button class="check" :class="{done:task.done}" @click="toggleTask(task)"><Check v-if="task.done" :size="13"/></button><span class="task-time">{{task.startTime}}</span><div @click="openTask(task)" style="cursor:pointer;min-width:0"><div class="task-title" :class="{done:task.done}">{{task.title}}</div><div class="task-stage">{{stageLabel(task.stage)}}<span v-if="taskProjectInfo(task)" class="task-project-badge" :style="{'--task-project-color':taskProjectInfo(task).color}" :title="`Проект: ${taskProjectInfo(task).name}`"><FolderKanban :size="10" aria-hidden="true"/><span>{{taskProjectInfo(task).name}}</span></span></div></div><span class="duration">{{task.duration}}м</span></div></div></article><div v-if="!planChains.length" class="empty card">Создай цепочку из заготовки, затем перенеси в неё задачи.</div></div>
          <div class="section-head plan-group-heading"><h2>{{taskFilter==='overdue'?'Просроченные свободные задачи':`Свободные задачи на ${selectedDate===todayKey?'сегодня':format(parseISO(selectedDate),'d MMMM',{locale:ru})}`}}</h2><span class="section-meta">{{taskFilter==='overdue'?'Все незавершённые задачи с прошедшей датой':'Только выбранные на этот день и ещё не добавленные в цепочки'}}</span></div><div class="card" style="overflow:hidden"><div v-for="task in planLooseTasks" :key="task.id" class="task-row plan-row movable-task" :class="{blocked:blocked(task),'long-press-active':longPressTaskId===task.id}" draggable="true" @dragstart="dragStart(task)" @dragend="cancelLongPress"><GripVertical class="drag-handle" :size="14" @pointerdown.stop="beginLongPress(task)"/><button class="check" :disabled="blocked(task)" :class="{done:task.done}" @click="toggleTask(task)"><Check v-if="task.done" :size="13"/><Link2 v-else-if="blocked(task)" :size="10"/></button><span class="task-time">{{format(parseISO(task.date),'d MMM',{locale:ru})}}</span><div @click="openTask(task)" style="cursor:pointer;min-width:0"><div class="task-title" :class="{done:task.done}">{{task.title}}</div><div class="task-stage">{{blocked(task)?'Ожидает зависимость':(task.startTime||'Без времени')}}<span v-if="taskProjectInfo(task)" class="task-project-badge" :style="{'--task-project-color':taskProjectInfo(task).color}" :title="`Проект: ${taskProjectInfo(task).name}`"><FolderKanban :size="10" aria-hidden="true"/><span>{{taskProjectInfo(task).name}}</span></span><span v-if="task.scheduling==='fixed'"> · 🔒 фиксировано</span><span v-if="isValidDayKey(task.dueDate)"> · срок {{format(parseISO(task.dueDate),'d MMM',{locale:ru})}}</span> <span v-for="tag in (task.tags||[]).slice(0,2)" :key="tag">· #{{tag}}</span></div></div><div class="row" style="flex:0"><select v-if="dayChains.length&&!task.done" class="mini-chain-select" aria-label="Переместить в цепочку" @change="moveTaskToChainMenu(task,$event.target.value);$event.target.value='' "><option value="">В цепочку…</option><option v-for="chain in dayChains" :key="chain.id" :value="chain.id">{{chain.title}}</option></select><button v-if="task.date<todayKey&&!task.done" class="mini-btn" @click="openTransfer(task)">Сегодня</button><span class="tag" :style="task.priority==='high'?{color:'#fda4af',background:'#3a1820'}:{}">{{task.priority==='high'?'Важно':task.duration+'м'}}</span></div></div><div v-if="!planLooseTasks.length" class="empty">{{taskFilter==='overdue'?'Просроченных свободных задач нет — проверь раскрытые цепочки выше.':'На выбранный день свободных задач нет. Выбери их в утреннем ритуале или измени дату задачи.'}}</div></div><details class="archive-box card"><summary><Archive :size="15"/> Архив и завершённое · {{archivedItems.length+completedForArchive.length}}</summary><div class="archive-list"><div v-for="task in completedForArchive" :key="task.id"><span>{{task.title}}<small>Выполнено · {{task.date}}<span v-if="taskProjectInfo(task)"> · {{taskProjectInfo(task).name}}</span></small></span><button @click="archiveTask(task)">В архив</button></div><div v-for="record in archivedItems" :key="record.id"><span>{{record.title||record.type}}<small>Архив · {{record.type}}</small></span><button @click="restoreArchived(record)">Восстановить</button></div><div v-if="!archivedItems.length&&!completedForArchive.length" class="empty">Архив пуст</div></div></details>
        </template>

        <template v-else-if="view==='calendar'">
          <div class="section-head" style="margin-top:0"><div><strong>{{calendarMode==='day'?format(parseISO(selectedDate),'d MMMM, EEEE',{locale:ru}):format(calendarMonth,'LLLL yyyy',{locale:ru})}}</strong><div class="section-meta">Планируй визуально и замечай перегрузку</div></div><div class="row" style="flex:0"><div class="segmented"><button v-for="m in [{id:'month',t:'Месяц'},{id:'week',t:'Неделя'},{id:'day',t:'День'}]" :key="m.id" :class="{active:calendarMode===m.id}" @click="calendarMode=m.id">{{m.t}}</button></div><button class="icon-btn" @click="calendarMode==='month'?calendarMonth=subMonths(calendarMonth,1):changeDay(-7)"><ChevronLeft :size="17"/></button><button class="icon-btn" @click="calendarMode==='month'?calendarMonth=addMonths(calendarMonth,1):changeDay(7)"><ChevronRight :size="17"/></button></div></div>
          <div v-if="calendarMode!=='day'" class="calendar-grid" :class="{'week-grid':calendarMode==='week'}"><div v-for="w in ['Пн','Вт','Ср','Чт','Пт','Сб','Вс']" :key="w" class="weekday">{{w}}</div><button v-for="d in monthDays" :key="d.toISOString()" class="day" :class="{muted:calendarMode==='month'&&!isSameMonth(d,calendarMonth),today:isToday(d),selected:format(d,'yyyy-MM-dd')===selectedDate}" @click="selectedDate=format(d,'yyyy-MM-dd');calendarMode='day'"><span class="day-number">{{format(d,'d')}}</span><div class="dots"><span v-for="r in dayRecords(d).slice(0,8)" :key="r.id" class="dot" :style="{background:r.type==='class'?'#38bdf8':r.type==='chain'?(r.color||'#8b5cf6'):r.done?'#34d399':r.priority==='high'?'#fb7185':'#52525b'}"></span></div><div v-if="calendarMode==='week'" class="week-items"><div v-for="lesson in classesForDate(d)" :key="lesson.id" class="week-class">{{lesson.start}} {{lesson.subject}}</div><div v-for="t in store.tasks.value.filter(t=>t.date===format(d,'yyyy-MM-dd')).slice(0,5)" :key="t.id" :title="taskProjectInfo(t)?`Проект: ${taskProjectInfo(t).name}`:t.title">{{t.startTime}} {{t.title}}<small v-if="taskProjectInfo(t)"> · {{taskProjectInfo(t).name}}</small></div></div></button></div>
          <div v-else><div class="capacity-strip" :class="{overload:capacity.overload}"><Gauge :size="17"/><div><strong>{{Math.round(capacity.planned/60*10)/10}} ч запланировано из {{Math.round(capacity.available/60*10)/10}} ч</strong><span v-if="capacity.overload">Перегрузка {{capacity.overload}} мин — убери или перенеси часть плана</span><span v-else>Свободный резерв {{capacity.free}} мин · дорога и сборы {{selectedClasses.length?50:0}} мин</span></div></div><div class="day-timeline card"><div v-for="hour in Array.from({length:16},(_,i)=>i+7)" :key="hour" class="time-slot" :class="{expanded:isHourExpanded(hour)}" :style="isHourExpanded(hour)?{height:(Math.max(1,timelineForHour(hour).length)*58+16)+'px'}:{}"><span>{{String(hour).padStart(2,'0')}}:00</span><div class="slot-line"></div><button v-for="(item,index) in timelineForHour(hour)" :key="item.id" class="timeline-event" :class="{'class-event':item.isClass,'commute-event':item.isCommute,'homework-event':item.type==='homework','habit-event':item.type==='habit'}" :style="timelineItemStyle(item,index,hour)" :title="item.type==='task'&&taskProjectInfo(item.source)?`Проект: ${taskProjectInfo(item.source).name}`:item.title" @click="openTimelineItem(item)">{{item.startTime}} · {{item.title}}<small v-if="item.type==='task'&&taskProjectInfo(item.source)">{{taskProjectInfo(item.source).name}}</small></button><button v-if="timelineForHour(hour).some(item=>item.lanes>1)" class="timeline-layers" :class="{active:isHourExpanded(hour)}" :title="isHourExpanded(hour)?'Собрать события':'Разложить события'" @click="toggleTimelineHour(hour)"><Layers :size="13"/>{{isHourExpanded(hour)?'Собрать':'Разложить'}}</button></div><button class="quick-add" style="margin:12px;width:calc(100% - 24px)" @click="view='tasks'"><Plus :size="14"/> Собрать цепочку в «Плане»</button></div></div>
        </template>

        <template v-else-if="view==='study'">
          <div class="study-hero card"><div><div class="eyebrow">УВП-412 · 1 семестр 2026–2027</div><h2>{{selectedAcademicWeek===1?'Первая':'Вторая'}} неделя</h2><p>{{format(studyWeekStart,'d MMMM',{locale:ru})}} — {{format(addDays(studyWeekStart,6),'d MMMM yyyy',{locale:ru})}}</p></div><div class="study-nav"><button class="icon-btn" aria-label="Предыдущая учебная неделя" @click="changeDay(-7)"><ChevronLeft :size="17"/></button><button class="ghost-btn" @click="selectedDate=todayKey">Текущая</button><button class="icon-btn" aria-label="Следующая учебная неделя" @click="changeDay(7)"><ChevronRight :size="17"/></button></div></div>
          <div v-if="upcomingHomework.length" class="study-homework card"><div class="section-head"><div><h2>Ближайшие задания</h2><div class="section-meta">Невыполненные · {{upcomingHomework.length}}</div></div></div><div v-for="item in upcomingHomework.slice(0,6)" :key="item.id" class="homework-row with-plan"><button class="check" @click="toggleHomework(item)"></button><div @click="openHomework({id:item.lessonId,subject:item.subject,kind:item.lessonKind,room:item.room},item.dueDate,item)"><strong>{{item.title}}</strong><span>{{item.subject}}</span></div><button class="plan-homework-btn" :class="{active:(item.plannedDates||[]).includes(selectedDate)}" @click="toggleHomeworkPlan(item)"><Target :size="12"/> {{(item.plannedDates||[]).includes(selectedDate)?'В плане':'В план'}}</button><span class="homework-due">{{format(parseISO(item.dueDate),'d MMM')}}</span></div></div>
          <div v-if="!isInSemester(selectedDate)" class="card empty">Эта дата находится вне периода семестра: {{format(parseISO(SEMESTER.start),'d MMMM',{locale:ru})}} — {{format(parseISO(SEMESTER.end),'d MMMM yyyy',{locale:ru})}}</div>
          <div v-else class="study-grid"><section v-for="(date,index) in studyWeekDays" :key="date.toISOString()" class="study-day" :class="{today:isToday(date)}"><header><div><strong>{{DAY_NAMES[index]}}</strong><span>{{format(date,'d MMMM',{locale:ru})}}</span></div><span v-if="isToday(date)" class="tag">Сегодня</span></header><div v-if="classesForDate(date).length" class="study-lessons"><article v-for="lesson in classesForDate(date)" :key="lesson.id" class="study-lesson"><div class="lesson-time"><span>{{lesson.pair}} пара</span><strong>{{lesson.start}}–{{lesson.end}}</strong></div><div class="lesson-main"><strong>{{lesson.subject}}</strong><span><component :is="lessonKindIcon(lesson.kind)" :size="12"/> {{lesson.kind}}</span><span v-if="lesson.teacher">{{lesson.teacher}}</span></div><div class="lesson-room"><span><MapPin :size="13"/><strong>{{lesson.room}}</strong></span><button class="homework-btn" @click="openHomework(lesson,date)"><NotebookPen :size="13"/> ДЗ <b v-if="homeworkForOccurrence(lesson,date).length">{{homeworkForOccurrence(lesson,date).length}}</b></button></div></article></div><div v-else class="study-free">Пар нет</div></section></div>
          <div class="schedule-note card"><GraduationCap :size="18"/><div><strong>Чередование рассчитано автоматически</strong><span>28 сентября 2026 — понедельник первой недели. Расписание действует с 1 сентября 2026 по 4 января 2027.</span></div></div>
        </template>

        <template v-else-if="view==='workouts'">
          <div class="card hero-card" style="margin-bottom:18px"><div class="eyebrow">Твоя система</div><h2 style="margin:7px 0">Сила растёт там, где виден прогресс</h2><p class="quote" style="max-width:600px;margin:0">Каждый рабочий подход сохраняется. Смотри динамику веса и объёма, а не полагайся на память.</p></div>
          <div class="segmented tabs"><button v-for="t in [{id:'programs',n:'Программы'},{id:'history',n:'История'},{id:'stats',n:'Прогресс'}]" :key="t.id" :class="{active:workoutTab===t.id}" @click="workoutTab=t.id">{{t.n}}</button></div>
          <div v-if="workoutTab==='programs'" class="workout-grid"><article v-for="w in store.workouts.value" :key="w.id" class="card workout-card"><div class="workout-day">День {{w.day}}</div><div class="workout-name">{{w.title}}</div><div v-for="ex in w.exercises.slice(0,4)" :key="ex.id" class="exercise-preview">{{ex.sets}} × {{ex.reps}} · {{ex.title}}</div><div class="row" style="margin-top:12px"><button class="primary-btn" @click="openWorkout(w)"><Play :size="14"/> Начать</button><button class="icon-btn" aria-label="Редактировать программу" @click="editWorkout(w)"><Pencil :size="14"/></button></div><div style="position:absolute;width:100px;height:100px;border-radius:50%;right:-40px;top:-40px" :style="{background:w.color+'18'}"></div></article></div>
          <div v-else-if="workoutTab==='history'" class="history-list"><article v-for="s in workoutSessions" :key="s.id" class="card history-card history-clickable" tabindex="0" role="button" @click="openSession(s)" @keydown.enter="openSession(s)"><div><strong>{{sessionTitle(s)}}</strong><div class="section-meta">{{format(parseISO(s.date),'d MMMM yyyy',{locale:ru})}}<span v-if="sessionDuration(s)"> · {{sessionDuration(s)}} мин</span></div></div><div class="history-summary"><div><strong>{{sessionCompletedSets(s)}}</strong><div class="section-meta">подходов</div></div><div><strong>{{Math.round(sessionVolume(s))}}</strong><div class="section-meta">кг объём</div></div><ChevronRight :size="18"/><button class="close" aria-label="Удалить тренировку" @click.stop="removeSession(s)"><Trash2 :size="13"/></button></div></article><div v-if="!workoutSessions.length" class="empty card">Заверши первую тренировку — здесь появится история</div></div>
          <div v-else class="stats-layout"><div class="card card-pad"><div class="section-head" style="margin-top:0"><div><h2>Динамика упражнения</h2><div class="section-meta">{{selectedExerciseStat==='all'?'Общий объём тренировок':'Лучший рабочий вес'}}</div></div><select class="select compact" v-model="selectedExerciseStat"><option value="all">Общий объём</option><option v-for="ex in exerciseOptions" :key="ex.id" :value="ex.id">{{ex.title}}</option></select></div><svg class="chart" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="График прогресса"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8b5cf6" stop-opacity=".45"/><stop offset="1" stop-color="#8b5cf6" stop-opacity="0"/></linearGradient></defs><polyline v-if="statPoints()" :points="`0,100 ${statPoints()} 100,100`" fill="url(#chartFill)" stroke="none"/><polyline v-if="statPoints()" :points="statPoints()" fill="none" stroke="#a78bfa" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div v-if="!exerciseStats.length" class="empty">Запиши вес и повторы в выполненных подходах</div><div v-else class="stat-cards"><div><strong>{{exerciseStats.at(-1)?.best}} кг</strong><span>Последний лучший вес</span></div><div><strong>{{Math.round(exerciseStats.at(-1)?.volume||0)}} кг</strong><span>Объём последней сессии</span></div><div><strong>{{exerciseStats.length}}</strong><span>Точек данных</span></div></div></div></div>
        </template>

        <template v-else-if="view==='habits'">
          <div class="card hero-card" style="margin-bottom:18px"><div class="eyebrow">Основа формы</div><h2 style="margin:7px 0">Действия отмечаем. Намерения держим в фокусе.</h2><div class="progress-row"><div class="progress-track"><div class="progress-fill" :style="{width:(trackableHabits.length?trackableHabits.filter(h=>habitValue(h)>=h.target).length/trackableHabits.length*100:0)+'%'}"></div></div></div></div>
          <div class="section-head"><div><h2>Отмечаемые ритуалы</h2><div class="section-meta">Конкретные действия, которые можно завершить</div></div><button class="ghost-btn" @click="openHabit()"><Plus :size="15"/> Добавить</button></div>
          <div class="settings-grid"><div v-for="h in trackableHabits" :key="h.id" class="card setting-card"><div style="display:flex;align-items:center;gap:13px"><div class="habit-icon" :style="{color:h.color,background:h.color+'18'}"><component :is="iconMap[h.icon]||Activity" :size="19"/></div><div><h3 style="margin:0">{{h.title}}</h3><div class="habit-sub">{{h.subtitle}}</div></div><button v-if="h.timerMinutes" class="habit-timer-btn large" @click="startRitualTimer(h)"><Timer :size="15"/> {{h.timerMinutes}} мин</button><button class="habit-toggle" style="margin-left:auto" :class="{done:habitValue(h)>=h.target}" @click="toggleHabit(h)"><Check v-if="habitValue(h)>=h.target" :size="14"/><span v-else>{{habitValue(h)}}/{{h.target}}</span></button><button class="chain-more" aria-label="Редактировать привычку" @click="openHabit(h)"><MoreHorizontal :size="17"/></button></div><div class="habit-calendar"><span v-for="i in 21" :key="i" :title="format(addDays(new Date(),i-21),'d MMM',{locale:ru})" :class="{done:(h.history?.[format(addDays(new Date(),i-21),'yyyy-MM-dd')]||0)>=h.target}"></span></div><div style="margin-top:13px;display:flex;justify-content:space-between" class="section-meta"><span>Серия · <strong style="color:#f59e0b">{{habitStreak(h)}} дней</strong></span><span>30 дней · <strong style="color:#34d399">{{habitRate(h)}}%</strong></span></div></div></div>
          <div class="section-head"><div><h2>Намерения и ограничения</h2><div class="section-meta">Напоминания без галочек и давления серии</div></div><button class="ghost-btn" @click="openHabit({kind:'intention'})"><Plus :size="15"/> Намерение</button></div>
          <div class="settings-grid"><div v-for="h in intentions" :key="h.id" class="card setting-card intention-setting"><div style="display:flex;align-items:center;gap:13px"><div class="habit-icon" :style="{color:h.color,background:h.color+'18'}"><HeartPulse :size="19"/></div><div><h3 style="margin:0">{{h.title}}</h3><div class="habit-sub">{{h.subtitle}}</div></div><span class="intention-badge">Фокус дня</span><button class="chain-more" @click="openHabit(h)"><MoreHorizontal :size="17"/></button></div></div></div>
        </template>

        <template v-else-if="view==='settings'">
          <div class="theme-panel card"><div class="theme-panel-head"><div><h3>Оформление</h3><p>Тема применяется сразу и сохраняется на этом устройстве.</p></div><span>{{themes.find(theme=>theme.id===currentTheme)?.name}}</span></div><div class="theme-grid"><button v-for="theme in themes" :key="theme.id" :class="{active:currentTheme===theme.id}" @click="applyTheme(theme.id)"><div class="theme-preview" :style="{background:theme.colors[0]}"><i v-for="color in theme.colors.slice(1)" :key="color" :style="{background:color}"></i></div><span><strong>{{theme.name}}</strong><em>{{theme.scheme}}</em><small>{{theme.description}}</small></span><Check v-if="currentTheme===theme.id" :size="15"/></button></div></div>
          <div class="settings-grid">
            <div class="card setting-card"><Cloud :size="21" color="#a78bfa"/><h3 style="margin-top:12px">Синхронизация устройств</h3><p>{{cloud.connected?`Выполнен вход: ${cloud.user?.email}. Последняя синхронизация ${formatSync()}. ${dirtyRecords} локальных изменений ожидают отправки.`:'Подключите бесплатный Supabase, чтобы один план был доступен на iPhone и компьютере.'}}</p><button class="primary-btn" @click="cloudOpen=true">{{cloud.connected?'Управление облаком':'Подключить облако'}}</button></div>
            <div v-if="cloud.conflicts.length" class="card setting-card conflict-card"><AlertCircle :size="21" color="#fb7185"/><h3 style="margin-top:12px">Конфликты между устройствами</h3><p>Ничего не перезаписано автоматически. Выбери версию для каждой записи.</p><div v-for="conflict in cloud.conflicts" :key="conflict.id" class="conflict-row"><span>{{conflict.title}}</span><button @click="resolveCloudConflict(conflict.id,'local')">Эта версия</button><button @click="resolveCloudConflict(conflict.id,'remote')">Облачная</button></div></div>
            <div class="card setting-card"><Bell :size="21" color="#f59e0b"/><h3 style="margin-top:12px">Уведомления</h3><p>Напоминания о парах, ДЗ и таймерах. Для iPhone приложение должно быть добавлено на экран «Домой».</p><button class="ghost-btn" @click="requestNotifications">{{notificationPermission==='granted'?'Уведомления включены':'Разрешить уведомления'}}</button></div>
            <div class="card setting-card"><Ruler :size="21" color="#22c55e"/><h3 style="margin-top:12px">Самочувствие и измерения</h3><p v-if="latestMeasurements.length">Последняя запись {{format(parseISO(latestMeasurements[0].date),'d MMM',{locale:ru})}} · вес {{latestMeasurements[0].weight||'—'}} кг · сон {{latestMeasurements[0].sleep||'—'}} ч.</p><p v-else>Вес, сон, пульс, энергия и состояние поясницы — ввод занимает меньше минуты.</p><button class="ghost-btn" @click="openMeasurement"><Plus :size="15"/> Записать</button></div>
            <div class="card setting-card"><Clock3 :size="21" color="#a78bfa"/><h3 style="margin-top:12px">План и факт времени</h3><p>{{timeStats.sessions}} фокус-сессий · план {{timeStats.planned}} мин · факт {{timeStats.actual}} мин<span v-if="timeStats.ratio"> · {{timeStats.ratio}}%</span>.</p><button class="ghost-btn" @click="view='today'"><Target :size="15"/> Начать фокус</button></div>
            <div class="card setting-card insight-card"><BarChart3 :size="21" color="#06b6d4"/><h3 style="margin-top:12px">Рабочие выводы</h3><p>Ошибка оценки времени: <strong>{{productivityInsights.estimateError>0?'+':''}}{{productivityInsights.estimateError}}%</strong>. Полностью завершено цепочек: <strong>{{productivityInsights.chainRate}}%</strong>. Переносов: <strong>{{transferStats.count}}</strong>, главная причина — {{transferStats.top}}. В ожидании: {{productivityInsights.waiting}}.</p><small>Это живая аналитика, а не отдельный еженедельный обзор.</small></div>
            <div class="card setting-card"><ShieldCheck :size="21" color="#34d399"/><h3 style="margin-top:12px">Резервные версии</h3><p>Автоматическая копия создаётся раз в день. Хранятся последние 7 версий плюс переносимый JSON.</p><div class="row"><button class="ghost-btn" @click="makeBackup"><Save :size="15"/> Снимок</button><button class="ghost-btn" @click="exportData"><Download :size="15"/> JSON</button><label class="ghost-btn"><Upload :size="15"/> Импорт<input type="file" accept="application/json" hidden @change="importData"/></label></div><div class="backup-list"><button v-for="backup in backups.slice(0,3)" :key="backup.id" @click="restoreLocalBackup(backup.id)">{{format(new Date(backup.createdAt),'d MMM, HH:mm',{locale:ru})}} · {{backup.label}}</button></div></div>
            <div class="card setting-card"><RefreshCw :size="21" color="#60a5fa"/><h3 style="margin-top:12px">Обновление данных</h3><p>Принудительно отправить локальные изменения и получить свежий план со всех устройств.</p><button class="ghost-btn" :disabled="!cloud.connected" @click="doSync"><RefreshCw :size="15" :class="{spin:cloud.syncing}"/> Синхронизировать</button></div>
            <div class="card setting-card"><Timer :size="21" color="#f59e0b"/><h3 style="margin-top:12px">Звук таймеров</h3><p>Используется файл <code>public/sounds/timer-end.mp3</code>. Пока файла нет, приложение воспроизводит встроенный тройной сигнал.</p><button class="ghost-btn" @click="playTimerSound"><Play :size="15"/> Проверить звук</button></div>
            <div class="card setting-card"><Trash2 :size="21" color="#fb7185"/><h3 style="margin-top:12px">Начать заново</h3><p>Удаляет данные только на текущем устройстве. Используйте осторожно.</p><button class="ghost-btn danger-btn" @click="resetData">Сбросить локальные данные</button></div>
          </div>
        </template>
      </div>
    </main>

    <button class="fab" aria-label="Новая задача" title="Новая задача" @click="openTask()"><Plus :size="23"/></button>
    <nav class="mobile-nav"><button v-for="item in mobileNav" :key="item.id" :class="{active:view===item.id}" @click="setView(item.id)"><component :is="item.icon" :size="20"/><span>{{item.label}}</span></button></nav>

    <Transition name="fade"><div v-if="inboxOpen" class="modal-backdrop" @click.self="inboxOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Без организации — просто выгрузи из головы</div><div class="modal-title">Входящие</div></div><button class="close" @click="inboxOpen=false"><X :size="17"/></button></div><div class="inbox-capture"><input class="input" v-model="inboxText" autofocus placeholder="Мысль, дело, идея…" @keydown.enter.prevent="captureInbox"/><button class="primary-btn" @click="captureInbox"><Plus :size="16"/> Записать</button></div><div v-if="processingInbox" class="inbox-processor"><strong>{{processingInbox.title}}</strong><label><input type="checkbox" v-model="inboxProcess.actionable"/> Требует конкретного действия</label><template v-if="inboxProcess.actionable"><div class="row"><div class="field"><label>Проект</label><select class="select" v-model="inboxProcess.projectId"><option :value="null">Без проекта</option><option v-for="entry in projectTreeEntries" :key="entry.project.id" :value="entry.project.id">{{'— '.repeat(entry.depth)}}{{entry.project.title}}</option></select></div><div class="field"><label>Статус</label><select class="select" v-model="inboxProcess.status"><option value="planned">Запланировано</option><option value="someday">Когда-нибудь</option><option value="waiting">Ожидание</option></select></div></div><div class="row"><div class="field"><label>Дата</label><input class="input" type="date" v-model="inboxProcess.date"/></div><div class="field"><label>Оценка, мин</label><input class="input" type="number" v-model.number="inboxProcess.duration"/></div></div><div class="field"><label>Контекст</label><textarea class="textarea" rows="2" v-model="inboxProcess.notes"></textarea></div></template><div class="form-actions"><button class="ghost-btn" @click="processingInbox=null">Назад</button><button class="primary-btn" @click="finishInboxProcessing">{{inboxProcess.actionable?'Создать задачу':'Удалить как не требующее действия'}}</button></div></div><div v-else class="inbox-list"><div v-for="item in store.inbox.value" :key="item.id"><span>{{item.title}}</span><button @click="inboxToToday(item)">Разобрать</button><button class="close" @click="removeInbox(item)"><X :size="13"/></button></div><div v-if="!store.inbox.value.length" class="empty">Входящие разобраны</div></div></div></div></Transition>

    <Transition name="fade"><div v-if="reviewOpen" class="modal-backdrop" @click.self="reviewOpen=false"><div class="modal ritual-modal"><div class="modal-head"><div><div class="eyebrow">{{reviewMode==='morning'?'Осознанно выбери, ради чего начинается день':'Извлеки урок и запрограммируй новое поведение'}}</div><div class="modal-title">{{reviewMode==='morning'?'Утренний ритуал':'Вечерний ритуал'}}</div></div><button class="close" @click="reviewOpen=false"><X :size="17"/></button></div><template v-if="reviewMode==='morning'"><section class="ritual-step"><b>1</b><div><h4>Зачем я проснулся?</h4><p>Выбери только основные задачи на день. Подготовки и детали цепочек настраиваются отдельно во вкладке «План».</p><div class="ritual-choice-list"><button v-for="item in ritualActions" :key="item.key" :class="{active:reviewForm.selectedSubtasks.includes(item.key)}" @click="toggleRitualSubtask(item.key)"><span class="check" :class="{done:reviewForm.selectedSubtasks.includes(item.key)}"><Check v-if="reviewForm.selectedSubtasks.includes(item.key)" :size="11"/></span><span><strong>{{item.title}}</strong><small>{{item.project?projectPath(item.project)+' · ':''}}Задача · {{item.task.date}}</small></span></button><div v-if="!ritualActions.length" class="ritual-empty">Создай свободную незавершённую задачу во вкладке «План» — подготовки из цепочек здесь намеренно не показываются.</div></div><div class="field compact"><label>Смысл или главный результат дня</label><input class="input" v-model="reviewForm.mainResult" placeholder="Одной фразой: ради чего этот день?"/></div></div></section><section class="ritual-step"><b>2</b><div class="field"><h4>За что я благодарен миру?</h4><p>Заметь то хорошее, что уже есть.</p><textarea class="textarea" rows="3" v-model="reviewForm.gratitude" placeholder="Сегодня я благодарен за…"></textarea></div></section><div class="field ritual-energy"><label>Энергия сейчас · {{reviewForm.energy}}/5</label><input class="range" type="range" min="1" max="5" v-model.number="reviewForm.energy"/></div><div class="review-summary"><span>Выбрано шагов: <strong>{{reviewForm.selectedSubtasks.length}}</strong></span><span>Нагрузка: <strong>{{Math.round(capacity.planned/60*10)/10}} ч</strong></span><span v-if="capacity.overload" class="danger">Перегрузка {{capacity.overload}} мин</span></div></template><template v-else><section class="ritual-step"><b>1</b><div class="field"><h4>Какие уроки я получил?</h4><p>Что произошло? На что стоит обратить внимание? Что пытался сказать окружающий мир? В чём я могу стать лучше, а что было лишним?</p><textarea class="textarea" rows="4" v-model="reviewForm.lessons" placeholder="Ситуация, моя реакция и урок…"></textarea></div></section><section class="ritual-step"><b>2</b><div class="field"><h4>Как это исправить?</h4><p>Найди конкретный сбой в поведении или системе и придумай небольшое исправление.</p><textarea class="textarea" rows="3" v-model="reviewForm.correction" placeholder="Сбой был в… В следующий раз я изменю…"></textarea></div></section><section class="ritual-step"><b>3</b><div class="field"><h4>Медитация намерения</h4><p>Представь повторение ситуации и заранее выбери новое действие.</p><textarea class="textarea" rows="3" v-model="reviewForm.intention" placeholder="Если ситуация повторится, то я…"></textarea></div></section><section v-if="unfinishedDayChains.length" class="ritual-step"><b>4</b><div><h4>Незавершённые цепочки</h4><p>Реши судьбу остатка, не переноси его автоматически.</p><div class="unfinished-chain" v-for="chain in unfinishedDayChains" :key="chain.id"><span><strong>{{chain.title}}</strong><small>{{tasksForChain(chain.id).filter(task=>!task.done).length}} действий осталось</small></span><button @click="carryChainRemainder(chain)">На завтра</button><button @click="releaseChainTasks(chain)">В свободные</button></div></div></section><div class="field ritual-energy"><label>Оценка дня · {{reviewForm.eveningScore}}/5</label><input class="range" type="range" min="1" max="5" v-model.number="reviewForm.eveningScore"/></div></template><div class="form-actions"><button class="ghost-btn" @click="reviewOpen=false">Позже</button><button class="primary-btn" @click="saveReview"><Check :size="15"/> Завершить ритуал</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="projectOpen" class="modal-backdrop" @click.self="projectOpen=false"><div class="modal"><div class="modal-head"><div class="modal-title">{{editingProject.id?'Настроить проект':'Новый проект'}}</div><button class="close" @click="projectOpen=false"><X :size="17"/></button></div><div class="field"><label>Название</label><input class="input" v-model="editingProject.title" autofocus placeholder="Например, Математика"/></div><div class="field"><label>Родительский проект</label><select class="select" v-model="editingProject.parentProjectId"><option :value="null">Корневой проект</option><option v-for="entry in projectParentOptions" :key="entry.project.id" :value="entry.project.id">{{'— '.repeat(entry.depth)}}{{entry.project.title}}</option></select><small class="field-hint">Например: «Учёба» — проект, а предметы — его подпроекты.</small></div><div class="field"><label>Предмет для автоматической привязки ДЗ</label><select class="select" v-model="editingProject.homeworkSubject"><option :value="null">Не привязывать к предмету</option><option v-for="subject in homeworkSubjectOptions" :key="subject" :value="subject">{{subject}}</option></select><small class="field-hint">Задачи в этом проекте и подпроектах автоматически появятся как домашнее задание по выбранному предмету.</small></div><div class="field"><label>Измеримый результат</label><input class="input" v-model="editingProject.outcome" placeholder="Что означает «готово»?"/></div><div class="row"><div class="field"><label>Целевая дата</label><input class="input" type="date" v-model="editingProject.targetDate"/></div><div class="field"><label>Цвет</label><input class="input color-input" type="color" v-model="editingProject.color"/></div></div><div class="form-actions"><button v-if="editingProject.id" class="ghost-btn danger-btn" style="margin-right:auto" @click="deleteProject"><Archive :size="14"/> Архив</button><button class="ghost-btn" @click="projectOpen=false">Отмена</button><button class="primary-btn" @click="saveProject">Сохранить</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="measurementOpen" class="modal-backdrop" @click.self="measurementOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Быстрый чек-ин</div><div class="modal-title">Самочувствие</div></div><button class="close" @click="measurementOpen=false"><X :size="17"/></button></div><div class="row"><div class="field"><label>Вес, кг</label><input class="input" type="number" step="0.1" v-model="editingMeasurement.weight"/></div><div class="field"><label>Сон, часов</label><input class="input" type="number" step="0.5" v-model="editingMeasurement.sleep"/></div><div class="field"><label>Пульс</label><input class="input" type="number" v-model="editingMeasurement.pulse"/></div></div><div class="field"><label>Энергия · {{editingMeasurement.energy}}/5</label><input class="range" type="range" min="1" max="5" v-model.number="editingMeasurement.energy"/></div><div class="field"><label>Дискомфорт в пояснице · {{editingMeasurement.backPain}}/10</label><input class="range" type="range" min="0" max="10" v-model.number="editingMeasurement.backPain"/></div><div class="form-actions"><button class="ghost-btn" @click="measurementOpen=false">Отмена</button><button class="primary-btn" @click="saveMeasurement">Сохранить</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="transferOpen" class="modal-backdrop" @click.self="transferOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Не обвинять — улучшать систему</div><div class="modal-title">Почему переносим?</div></div><button class="close" @click="transferOpen=false"><X :size="17"/></button></div><div class="reason-grid"><button v-for="reason in ['Не хватило времени','Переоценил силы','Жду другого человека','Помешало срочное','Низкая энергия','Потеряло актуальность']" :key="reason" :class="{active:transferReason===reason}" @click="transferReason=reason">{{reason}}</button></div><div class="form-actions"><button class="ghost-btn" @click="transferOpen=false">Отмена</button><button class="primary-btn" @click="confirmTransfer">Перенести на сегодня</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="quickOpen" class="modal-backdrop" @click.self="quickOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Быстрый планировщик</div><div class="modal-title">Собрать цепочку</div></div><button class="close" @click="quickOpen=false"><X :size="17"/></button></div>
      <div class="templates"><button class="template" @click="chooseTemplate('focus')"><Coffee :size="20"/>Фокус-работа</button><button class="template" @click="chooseTemplate('workout')"><Dumbbell :size="20"/>Тренировка</button><button class="template" @click="chooseTemplate('custom')"><Zap :size="20"/>Своя цепочка</button></div>
      <div v-if="quick.template==='workout'" class="field preset-picker"><label>Выбери тренировочную цепочку</label><select class="select" v-model="quick.workoutId" @change="chooseWorkoutPreset"><option v-for="workout in store.workouts.value" :key="workout.id" :value="workout.id">День {{workout.day}} · {{workout.title}}</option></select><div class="preset-preview"><span v-for="ex in store.workouts.value.find(w=>w.id===quick.workoutId)?.exercises.slice(0,4)" :key="ex.id">{{ex.title}}</span></div></div><div class="field"><label>Результат / название потока</label><input class="input" v-model="quick.title" autofocus/></div><div class="row"><div class="field"><label>Дата</label><input type="date" class="input" v-model="quick.date"/></div><div class="field"><label>Начало</label><input type="time" class="input" v-model="quick.startTime"/></div></div>
      <div class="field"><label>Шаги — время рассчитается автоматически</label><div v-for="step in quick.steps" :key="step.id" class="row" style="margin-bottom:7px"><select class="select" v-model="step.stage" style="max-width:125px"><option value="prepare">Подготовка</option><option value="action">Действие</option><option value="finish">Финиш</option></select><input class="input" v-model="step.title"/><input class="input" type="number" v-model="step.duration" style="max-width:72px"/></div><button class="quick-add" @click="addQuickStep"><Plus :size="14"/> Добавить шаг</button></div><div class="form-actions"><button class="ghost-btn" @click="quickOpen=false">Отмена</button><button class="primary-btn" @click="saveChain">Добавить в день <ArrowRight :size="15"/></button></div>
    </div></div></Transition>

    <Transition name="fade"><div v-if="homeworkOpen && editingHomework" class="modal-backdrop" @click.self="closeHomework"><div class="modal homework-modal"><div class="modal-head"><div><div class="eyebrow">{{editingHomework.subject}}</div><div class="modal-title">{{editingHomework.id?'Изменить домашнее задание':'Добавить домашнее задание'}}</div></div><button class="close" @click="closeHomework"><X :size="17"/></button></div><div class="field"><label>Что нужно сделать?</label><input class="input" v-model="editingHomework.title" autofocus placeholder="Например, закончить лабораторную №2" @keydown.enter.prevent="saveHomework"/></div><div class="field"><label>К какой паре выполнить</label><input class="input" type="date" v-model="editingHomework.dueDate"/><button class="next-lesson-btn" @click="editingHomework.dueDate=nextLessonDate({id:editingHomework.lessonId},editingHomework.dueDate)"><ArrowRight :size="13"/> Перенести к следующей такой паре</button></div><div class="row"><div class="field"><label>Плановое время</label><input class="input" type="time" v-model="editingHomework.plannedTime"/></div><div class="field"><label>Оценка, минут</label><input class="input" type="number" min="5" step="5" v-model.number="editingHomework.estimatedMinutes"/></div></div><div class="field"><label>Условие, ссылка или комментарий</label><textarea class="textarea" rows="4" v-model="editingHomework.notes" placeholder="Страница, номер задания, ссылка на материалы…"></textarea></div><label v-if="editingHomework.id" class="homework-complete-switch"><input type="checkbox" v-model="editingHomework.done"/><span>Задание выполнено</span></label><div v-if="homeworkError" class="form-error" role="alert"><AlertCircle :size="14"/>{{homeworkError}}</div><div class="form-actions"><button v-if="editingHomework.id" class="ghost-btn danger-btn" style="margin-right:auto" @click="deleteHomework"><Trash2 :size="15"/> Удалить</button><button class="ghost-btn" :disabled="homeworkSaving" @click="closeHomework">Отмена</button><button class="primary-btn" :disabled="homeworkSaving" @click="saveHomework"><RefreshCw v-if="homeworkSaving" :size="15" class="spin"/><Save v-else :size="15"/> {{homeworkSaving?'Сохраняю…':'Сохранить'}}</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="taskOpen" class="modal-backdrop" @click.self="taskOpen=false"><div class="modal"><div class="modal-head"><div class="modal-title">{{editingTask.id?'Изменить действие':'Быстрое действие'}}</div><button class="close" @click="taskOpen=false"><X :size="17"/></button></div><div class="field"><label>Что нужно сделать?</label><input class="input" v-model="editingTask.title" autofocus/></div><div class="field"><label>Цепочка</label><select class="select" v-model="editingTask.chainId"><option :value="null">Без цепочки</option><option v-for="chain in store.chains.value.filter(c=>c.date===editingTask.date)" :key="chain.id" :value="chain.id">{{chain.title}}</option></select></div><div class="row"><div class="field"><label>Дата</label><input type="date" class="input" v-model="editingTask.date"/></div><div class="field"><label>Время</label><input type="time" class="input" v-model="editingTask.startTime"/></div><div class="field"><label>Минут</label><input type="number" class="input" v-model="editingTask.duration"/></div></div><div class="row"><div class="field"><label>Статус</label><select class="select" v-model="editingTask.status"><option value="inbox">Входящие</option><option value="someday">Когда-нибудь</option><option value="planned">Запланировано</option><option value="in-progress">В работе</option><option value="waiting">Ожидание</option><option value="blocked">Заблокировано</option><option value="completed">Выполнено</option><option value="cancelled">Отменено</option></select></div><div class="field"><label>Крайний срок</label><input type="date" class="input" v-model="editingTask.dueDate"/><button v-if="editingTask.dueDate" class="next-lesson-btn" @click="buildDeadlinePlan">Предложить обратный план</button></div><div class="field"><label>Положение во времени</label><select class="select" v-model="editingTask.scheduling"><option value="flexible">Гибкая — можно двигать</option><option value="fixed">Фиксированная — не двигать</option></select></div></div><div class="row"><div class="field"><label>Этап</label><select class="select" v-model="editingTask.stage"><option value="prepare">Подготовка</option><option value="action">Действие</option><option value="finish">Завершение</option></select></div><div class="field"><label>Приоритет</label><select class="select" v-model="editingTask.priority"><option value="normal">Обычный</option><option value="medium">Средний</option><option value="high">Высокий</option></select></div></div><div class="row"><div class="field"><label>Повторение</label><select class="select" v-model="editingTask.recurrence"><option value="none">Не повторять</option><option value="daily">Каждый день</option><option value="weekdays">По будням</option><option value="weekly">Каждую неделю</option></select></div><div class="field"><label>Энергия</label><select class="select" v-model="editingTask.energy"><option value="low">Низкая</option><option value="medium">Средняя</option><option value="high">Высокая</option></select></div></div><div class="row"><div class="field"><label>Проект</label><select class="select" v-model="editingTask.projectId"><option :value="null">Без проекта</option><option v-for="entry in projectTreeEntries" :key="entry.project.id" :value="entry.project.id">{{'— '.repeat(entry.depth)}}{{entry.project.title}}</option></select><small v-if="homeworkSubjectForProject(editingTask.projectId)" class="field-hint">Автоматически появится в ДЗ по предмету «{{homeworkSubjectForProject(editingTask.projectId)}}».</small></div><div class="field"><label>Контрольная точка</label><select class="select" v-model="editingTask.deadlineKind"><option value="">Обычная задача</option><option>Лабораторная</option><option>Контрольная</option><option>Зачёт</option><option>Экзамен</option><option>Защита</option></select></div></div><div class="field"><label>Теги через запятую</label><input class="input" v-model="editingTask.tagsText" placeholder="работа, компьютер, фокус"/></div><div class="field"><label>Чек-лист <button v-if="editingTask.deadlineKind" class="inline-action" @click="generateDeadlineSteps">Собрать этапы автоматически</button></label><div v-for="sub in editingTask.subtasks" :key="sub.id" class="row" style="margin-bottom:6px"><button class="check" :class="{done:sub.done}" @click="sub.done=!sub.done"><Check v-if="sub.done" :size="12"/></button><input class="input" v-model="sub.title" placeholder="Промежуточный результат"/></div><button class="quick-add" @click="addSubtask"><Plus :size="13"/> Добавить пункт</button></div><details class="dependency-box"><summary><GitBranch :size="14"/> Зависимости · {{editingTask.dependsOn?.length||0}}</summary><p class="section-meta">Действие будет заблокировано, пока выбранные пункты не завершены.</p><label v-for="candidate in store.tasks.value.filter(t=>t.id!==editingTask.id&&t.date<=editingTask.date).slice(-30)" :key="candidate.id" class="dependency-row"><input type="checkbox" :checked="editingTask.dependsOn?.includes(candidate.id)" @change="toggleDependency(candidate.id)"/><span>{{candidate.title}}</span><small>{{candidate.date}}</small></label></details><div class="field"><label>Заметка / критерий готовности</label><textarea class="textarea" rows="3" v-model="editingTask.notes" placeholder="Контекст, ссылка или ожидаемый результат"></textarea></div><details v-if="editingTask.revisionHistory?.length" class="dependency-box"><summary>История изменений · {{editingTask.revisionHistory.length}}</summary><button v-for="revision in [...editingTask.revisionHistory].reverse()" :key="revision.at" class="revision-row" @click="restoreTaskRevision(revision)">{{format(new Date(revision.at),'d MMM HH:mm',{locale:ru})}} · {{revision.title}}</button></details><div class="form-actions"><button v-if="editingTask.id" class="ghost-btn danger-btn" @click="deleteTask"><Trash2 :size="15"/></button><button v-if="editingTask.id" class="ghost-btn" style="margin-right:auto" @click="archiveTask(editingTask)"><Archive :size="15"/> Архив</button><button class="ghost-btn" @click="taskOpen=false">Отмена</button><button class="primary-btn" @click="saveTask">Сохранить</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="workoutOpen" class="modal-backdrop" @click.self="workoutOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">День {{selectedWorkout.day}}</div><div class="modal-title">{{selectedWorkout.title}}</div></div><button class="close" @click="workoutOpen=false"><X :size="17"/></button></div><div v-for="(ex,ei) in selectedWorkout.exercises" :key="ex.id" class="active-exercise"><div class="active-exercise-head"><div><strong>{{ex.title}}</strong><span class="section-meta">{{ex.reps}} · отдых {{Math.round(ex.rest/60)}}м</span></div><button class="mini-add-set" @click="addWorkoutSet(ei)"><Plus :size="14"/> Подход</button></div><div class="set-labels"><span>№</span><span>Вес</span><span>Повт.</span><span>RIR</span><span>Готово</span><span></span></div><div v-for="(set,si) in selectedWorkout.log[ei].sets" :key="set.id||si" class="workout-set-row"><span class="set-number">{{si+1}}</span><input class="input" inputmode="decimal" type="number" v-model="set.weight" :placeholder="set.previous||'кг'" aria-label="Вес"/><input class="input" inputmode="numeric" type="number" v-model="set.reps" placeholder="повт." aria-label="Повторения"/><input class="input" inputmode="numeric" type="number" min="0" max="5" v-model="set.rir" placeholder="RIR" title="Повторов в запасе" aria-label="RIR"/><button class="check" :class="{done:set.done}" :aria-label="set.done?'Вернуть подход':'Завершить подход'" @click="toggleSet(set, ex.rest)"><Check v-if="set.done" :size="13"/></button><button class="remove-set" aria-label="Убрать подход" @click="removeWorkoutSet(ei,si)"><X :size="14"/></button></div></div><div class="field"><label>Самочувствие и заметка тренировки</label><textarea class="textarea" rows="2" v-model="selectedWorkout.sessionNote" placeholder="Энергия, техника, что изменить в следующий раз"></textarea></div><div v-if="timerSeconds" class="card card-pad" style="display:flex;align-items:center;justify-content:space-between;margin-bottom:15px"><div><div class="eyebrow">Отдых</div><div style="font-size:25px;font-weight:800">{{timerText(timerSeconds)}}</div></div><div class="row" style="flex:0"><button class="ghost-btn" @click="startTimer(90)">1:30</button><button class="ghost-btn" @click="startTimer(150)">2:30</button><button class="ghost-btn" @click="startTimer(180)">3:00</button><button class="close" @click="stopTimer();timerSeconds=0"><X :size="15"/></button></div></div><div class="form-actions"><button class="ghost-btn" @click="workoutOpen=false">Закрыть</button><button class="primary-btn" :disabled="workoutSaving" @click="finishWorkout"><RefreshCw v-if="workoutSaving" :size="16" class="spin"/><Check v-else :size="16"/> {{workoutSaving?'Сохраняю…':'Завершить тренировку'}}</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="historyEditing && editingSession" class="modal-backdrop" @click.self="cancelSessionEdit"><div class="modal history-modal"><div class="modal-head"><div><div class="eyebrow">Исправление завершённой тренировки</div><div class="modal-title">{{sessionTitle(editingSession)}}</div></div><button class="close" @click="cancelSessionEdit"><X :size="17"/></button></div><div class="row"><div class="field"><label>Дата</label><input class="input" type="date" v-model="editingSession.date"/></div><div class="field"><label>Начало</label><input class="input" type="datetime-local" :value="editingSession.startedAt?.slice(0,16)" @input="editingSession.startedAt=new Date($event.target.value).toISOString()"/></div><div class="field"><label>Завершение</label><input class="input" type="datetime-local" :value="editingSession.finishedAt?.slice(0,16)" @input="editingSession.finishedAt=new Date($event.target.value).toISOString()"/></div></div><div class="field"><label>Заметка и самочувствие</label><textarea class="textarea" rows="2" v-model="editingSession.note"></textarea></div><section v-for="item in editingSession.log||[]" :key="item.exerciseId" class="active-exercise"><div class="active-exercise-head"><div><strong>{{sessionExercise(editingSession,item).title}}</strong><span class="section-meta">Исправь вес, повторы или RIR</span></div><button class="mini-add-set" @click="addHistoricalSet(item)"><Plus :size="14"/> Подход</button></div><div class="set-labels"><span>№</span><span>Вес</span><span>Повт.</span><span>RIR</span><span>Учесть</span><span></span></div><div v-for="(set,index) in item.sets" :key="set.id||index" class="workout-set-row"><span class="set-number">{{index+1}}</span><input class="input" type="number" inputmode="decimal" v-model="set.weight" placeholder="кг"/><input class="input" type="number" inputmode="numeric" v-model="set.reps" placeholder="повт."/><input class="input" type="number" inputmode="numeric" min="0" max="5" v-model="set.rir" placeholder="RIR"/><button class="check" :class="{done:set.done}" @click="set.done=!set.done"><Check v-if="set.done" :size="13"/></button><button class="remove-set" @click="removeHistoricalSet(item,index)"><X :size="14"/></button></div></section><div class="edit-summary">После сохранения объём и графики прогресса пересчитаются автоматически.</div><div class="form-actions"><button class="ghost-btn" @click="cancelSessionEdit">Отмена</button><button class="primary-btn" @click="saveSessionEdit"><Save :size="15"/> Сохранить исправления</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="historyOpen && selectedSession" class="modal-backdrop" @click.self="historyOpen=false"><div class="modal history-modal"><div class="modal-head"><div><div class="eyebrow">{{format(parseISO(selectedSession.date),'d MMMM yyyy',{locale:ru})}}</div><div class="modal-title">{{sessionTitle(selectedSession)}}</div></div><button class="close" @click="historyOpen=false"><X :size="17"/></button></div><div class="session-kpis"><div><strong>{{sessionCompletedSets(selectedSession)}}</strong><span>рабочих подходов</span></div><div><strong>{{Math.round(sessionVolume(selectedSession))}} кг</strong><span>общий объём</span></div><div><strong>{{sessionDuration(selectedSession)||'—'}}<template v-if="sessionDuration(selectedSession)"> мин</template></strong><span>продолжительность</span></div></div><div v-if="selectedSession.note" class="session-note"><span>Заметка</span>{{selectedSession.note}}</div><section v-for="item in selectedSession.log||[]" :key="item.exerciseId" class="history-exercise"><div class="history-exercise-head"><strong>{{sessionExercise(selectedSession,item).title}}</strong><span>{{item.sets.filter(set=>set.done).length}} подходов</span></div><div class="history-set-table"><div class="history-set-row labels"><span>Подход</span><span>Вес</span><span>Повторы</span><span>RIR</span><span>Объём</span></div><div v-for="(set,index) in item.sets.filter(set=>set.done)" :key="set.id||index" class="history-set-row"><span>{{index+1}}</span><strong>{{set.weight||'—'}} кг</strong><span>{{set.reps||'—'}}</span><span>{{set.rir!==''&&set.rir!=null?set.rir:'—'}}</span><span>{{set.weight&&set.reps?Math.round(+set.weight*+set.reps)+' кг':'—'}}</span></div><div v-if="!item.sets.some(set=>set.done)" class="section-meta" style="padding:12px">Нет завершённых подходов</div></div></section><div class="form-actions"><button class="ghost-btn danger-btn" style="margin-right:auto" @click="removeSession(selectedSession)"><Trash2 :size="15"/> Удалить запись</button><button class="ghost-btn" @click="editSession"><Pencil :size="15"/> Исправить</button><button class="primary-btn" @click="historyOpen=false">Готово</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="chainTemplateOpen && editingChainTemplate" class="modal-backdrop" @click.self="chainTemplateOpen=false"><div class="modal chain-template-modal"><div class="modal-head"><div><div class="eyebrow">Многоразовая подготовка</div><div class="modal-title">{{editingChainTemplate.id?'Настроить заготовку':'Новая заготовка цепочки'}}</div></div><button class="close" @click="chainTemplateOpen=false"><X :size="17"/></button></div><div class="row"><div class="field"><label>Название цепочки</label><input class="input" v-model="editingChainTemplate.title" placeholder="Например, Учебный блок"/></div><div class="field"><label>Иконка</label><select class="select" v-model="editingChainTemplate.icon"><option value="activity">Действие</option><option value="briefcase">Работа</option><option value="dumbbell">Тренировка</option></select></div><div class="field"><label>Цвет</label><input class="input color-input" type="color" v-model="editingChainTemplate.color"/></div></div><div class="field"><label>Подготовки</label><p class="field-hint">Они создаются автоматически перед выбранными ниже задачами.</p><div v-for="(step,index) in editingChainTemplate.preparations" :key="step.id" class="template-step-row"><GripVertical :size="14"/><input class="input" v-model="step.title" placeholder="Что подготовить?"/><input class="input" type="number" min="1" step="5" v-model.number="step.duration"/><span>мин</span><button class="close" @click="removeTemplatePreparation(index)"><X :size="13"/></button></div><button class="quick-add" @click="addTemplatePreparation"><Plus :size="13"/> Добавить подготовку</button></div><div class="template-use-box"><strong>Собрать отдельную цепочку на день</strong><div class="row"><div class="field" style="flex:2"><label>Название этой цепочки</label><input class="input" v-model="editingChainTemplate.instanceTitle" placeholder="Например, Университет утром"/></div><div class="field"><label>Дата</label><input class="input" type="date" v-model="editingChainTemplate.useDate" @change="editingChainTemplate.selectedTaskIds=[]"/></div><div class="field"><label>Начало</label><input class="input" type="time" v-model="editingChainTemplate.useTime"/></div></div><div class="chain-builder-tasks"><label>Задачи внутри цепочки · выбрано {{editingChainTemplate.selectedTaskIds.length}}</label><button v-for="task in chainBuilderTasks" :key="task.id" :class="{active:editingChainTemplate.selectedTaskIds.includes(task.id)}" @click="toggleChainBuilderTask(task.id)"><span class="check" :class="{done:editingChainTemplate.selectedTaskIds.includes(task.id)}"><Check v-if="editingChainTemplate.selectedTaskIds.includes(task.id)" :size="11"/></span><span><strong>{{task.title}}</strong><small>{{task.startTime||'Без времени'}} · {{task.duration}} мин<span v-if="task.projectId"> · {{projectPath(store.projects.value.find(project=>project.id===task.projectId))}}</span></small></span></button><p v-if="!chainBuilderTasks.length">На выбранный день нет свободных задач. Сначала выбери задачи в утреннем ритуале или создай их в «Плане».</p></div><button v-if="!schedulePreview" class="primary-btn assemble-chain-btn" @click="previewChainSchedule"><Clock3 :size="14"/> Проверить расписание</button><div v-else class="schedule-preview" :class="{conflict:schedulePreview.conflicts.length}"><div><strong>Предпросмотр</strong><span>Запрошено {{fromMinutes(schedulePreview.requested)}}–{{fromMinutes(schedulePreview.requested+schedulePreview.duration)}}</span><span v-if="schedulePreview.conflicts.length">Конфликты: {{schedulePreview.conflicts.map(item=>item.title).join(', ')}}</span><b>Предлагается {{fromMinutes(schedulePreview.suggested)}}–{{fromMinutes(schedulePreview.end)}}</b></div><button class="ghost-btn" @click="schedulePreview=null">Изменить</button><button class="primary-btn" @click="createChainFromTemplate()"><Check :size="14"/> Применить</button></div></div><div class="form-actions"><button v-if="editingChainTemplate.id" class="ghost-btn danger-btn" style="margin-right:auto" @click="deleteChainTemplate"><Trash2 :size="14"/> Удалить</button><button class="ghost-btn" @click="chainTemplateOpen=false">Отмена</button><button class="primary-btn" @click="saveChainTemplate"><Save :size="14"/> Сохранить заготовку</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="chainOpen" class="modal-backdrop" @click.self="chainOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Управление потоком</div><div class="modal-title">Настроить цепочку</div></div><button class="close" @click="chainOpen=false"><X :size="17"/></button></div><div class="field"><label>Название</label><input class="input" v-model="editingChain.title"/></div><div class="row"><div class="field"><label>Дата</label><input class="input" type="date" v-model="editingChain.date"/></div><div class="field"><label>Старт</label><input class="input" type="time" v-model="editingChain.startTime"/></div><div class="field"><label>Цвет</label><input class="input color-input" type="color" v-model="editingChain.color"/></div></div><div class="field"><label>Положение во времени</label><select class="select" v-model="editingChain.scheduling"><option value="flexible">Гибкая — планировщик может предложить сдвиг</option><option value="fixed">Фиксированная — не двигать</option></select></div><p class="quote">Цепочка отображается одной задачей. Подготовки добавляются здесь, а основные задачи переносятся в неё удержанием за маркер во вкладке «План».</p><button class="quick-add" @click="addPreparationToChain"><Plus :size="14"/> Добавить подготовку в эту цепочку</button><div class="form-actions chain-modal-actions"><button class="ghost-btn danger-btn" @click="deleteChain"><Trash2 :size="15"/> Удалить</button><button class="ghost-btn" @click="archiveChain(editingChain)"><Archive :size="15"/> Архив</button><button class="ghost-btn" @click="duplicateChain"><Copy :size="15"/> На завтра</button><button class="primary-btn" @click="saveChainEdit"><Save :size="15"/> Сохранить</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="habitOpen" class="modal-backdrop" @click.self="habitOpen=false"><div class="modal"><div class="modal-head"><div class="modal-title">{{editingHabit.id?'Настроить привычку':'Новая привычка'}}</div><button class="close" @click="habitOpen=false"><X :size="17"/></button></div><div class="field"><label>Тип</label><div class="kind-selector"><button :class="{active:editingHabit.kind==='trackable'}" @click="editingHabit.kind='trackable'"><CheckCircle2 :size="16"/><span>Отмечаемый ритуал<small>Есть выполнение и серия</small></span></button><button :class="{active:editingHabit.kind==='intention'}" @click="editingHabit.kind='intention'"><Target :size="16"/><span>Намерение<small>Только напоминание</small></span></button></div></div><div class="field"><label>Название</label><input class="input" v-model="editingHabit.title" autofocus/></div><div class="field"><label>Краткая цель</label><input class="input" v-model="editingHabit.subtitle" placeholder="Например, 5 × 500 мл или Не перекусывать"/></div><div class="row"><div v-if="editingHabit.kind==='trackable'" class="field"><label>Количество в день</label><input class="input" type="number" min="1" v-model.number="editingHabit.target"/></div><div v-if="editingHabit.kind==='trackable'" class="field"><label>Таймер, минут (0 — без таймера)</label><input class="input" type="number" min="0" v-model.number="editingHabit.timerMinutes"/></div><div class="field"><label>Цвет</label><input class="input color-input" type="color" v-model="editingHabit.color"/></div></div><div v-if="editingHabit.kind==='trackable'" class="field"><label>Предпочтительное время в дневном таймлайне</label><input class="input" type="time" v-model="editingHabit.preferredTime"/></div><div class="field"><label>Дни выполнения</label><div class="weekday-picker"><button v-for="d in [{v:1,t:'Пн'},{v:2,t:'Вт'},{v:3,t:'Ср'},{v:4,t:'Чт'},{v:5,t:'Пт'},{v:6,t:'Сб'},{v:0,t:'Вс'}]" :key="d.v" :class="{active:editingHabit.schedule?.includes(d.v)}" @click="toggleHabitDay(d.v)">{{d.t}}</button></div></div><div class="form-actions"><button v-if="editingHabit.id" class="ghost-btn danger-btn" style="margin-right:auto" @click="archiveHabit"><Archive :size="15"/> Архив</button><button class="ghost-btn" @click="habitOpen=false">Отмена</button><button class="primary-btn" @click="saveHabit">Сохранить</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="workoutEditOpen" class="modal-backdrop" @click.self="workoutEditOpen=false"><div class="modal"><div class="modal-head"><div class="modal-title">Редактор программы</div><button class="close" @click="workoutEditOpen=false"><X :size="17"/></button></div><div class="field"><label>Название</label><input class="input" v-model="editingWorkout.title"/></div><div class="field"><label>Упражнения</label><div v-for="(ex,i) in editingWorkout.exercises" :key="ex.id" class="exercise-editor"><GripVertical :size="14"/><input class="input" v-model="ex.title"/><input class="input small" type="number" v-model.number="ex.sets" title="Подходы"/><input class="input small" v-model="ex.reps" title="Повторения"/><button class="close" @click="editingWorkout.exercises.splice(i,1)"><X :size="13"/></button></div><button class="quick-add" @click="addExercise"><Plus :size="14"/> Добавить упражнение</button></div><div class="form-actions"><button class="ghost-btn" @click="workoutEditOpen=false">Отмена</button><button class="primary-btn" @click="saveWorkout">Сохранить программу</button></div></div></div></Transition>

    <Transition name="fade"><div v-if="focusPickerOpen" class="modal-backdrop focus-picker-backdrop" @click.self="focusPickerOpen=false"><div class="modal focus-picker" role="dialog" aria-modal="true" aria-label="Выбрать фокус дня"><div class="modal-head"><div><div class="eyebrow">Порядок можно менять в любой момент</div><div class="modal-title">На чём сфокусироваться сейчас?</div></div><button class="close" @click="focusPickerOpen=false"><X :size="17"/></button></div><button class="smart-focus-option" @click="useSmartFocus"><Sparkles :size="17"/><span><strong>Выбирать автоматически</strong><small>Учитывать просрочку, время, приоритет и зависимости</small></span></button><div class="focus-option-label">Незавершённые действия на {{format(parseISO(selectedDate),'d MMMM',{locale:ru})}}</div><div class="focus-options"><button v-for="task in focusCandidates" :key="task.id" :class="{selected:activeTask?.id===task.id}" @click="selectDayFocus(task)"><span class="focus-option-date" :class="{overdue:task.date<selectedDate}">{{task.date===selectedDate?(task.startTime||'Сегодня'):format(parseISO(task.date),'d MMM',{locale:ru})}}</span><span><strong>{{task.title}}</strong><small>{{task.date<selectedDate?'Не завершено ранее':stageLabel(task.stage)}} · {{task.duration||0}} мин<span v-if="taskProjectInfo(task)"> · {{taskProjectInfo(task).name}}</span></small></span><Check v-if="activeTask?.id===task.id" :size="16"/></button><div v-if="!focusCandidates.length" class="empty">Все действия завершены</div></div></div></div></Transition>

    <Transition name="fade"><div v-if="focusOpen && focusedTask" class="focus-overlay"><button class="focus-close" type="button" aria-label="Свернуть режим сейчас" @click="minimizeFocusMode"><Minimize2 :size="20"/></button><div class="focus-content"><div class="eyebrow">Сейчас имеет значение только это</div><h1>{{focusedTask.title}}</h1><div v-if="taskProjectInfo(focusedTask)" class="task-project-badge focus-project-badge" :style="{'--task-project-color':taskProjectInfo(focusedTask).color}" :title="`Проект: ${taskProjectInfo(focusedTask).name}`"><FolderKanban :size="11" aria-hidden="true"/><span>{{taskProjectInfo(focusedTask).name}}</span></div><p v-if="focusedTask.notes">{{focusedTask.notes}}</p><div v-if="focusedTask.subtasks?.length" class="focus-checklist"><button v-for="sub in focusedTask.subtasks" :key="sub.id" @click="toggleSubtask(focusedTask,sub)"><span class="check" :class="{done:sub.done}"><Check v-if="sub.done" :size="13"/></span>{{sub.title}}</button></div><div class="focus-timer">{{timerText(focusSeconds)}}</div><div class="focus-actions"><button class="icon-btn big" @click="resetFocus"><RotateCcw :size="20"/></button><button class="primary-btn big" @click="toggleFocusTimer"><component :is="focusRunning?Pause:Play" :size="21"/>{{focusRunning?'Пауза':'Продолжить'}}</button><button class="primary-btn big success" @click="finishFocusedTask"><Check :size="21"/>Готово</button></div><div class="focus-support"><div><span>Меня отвлекло:</span><button v-for="type in ['Телефон','Человек','Усталость','Мысль','Непонятен шаг']" :key="type" @click="logDistraction(type)">{{type}}</button><b v-if="focusDistractions.length">{{focusDistractions.length}}</b></div><form @submit.prevent="captureFocusInbox"><input v-model="focusInboxText" placeholder="Убрать постороннюю мысль во Входящие"/><button>Сохранить</button></form></div><div class="section-meta">Критерий готовности — в заметке задачи. Следующий шаг появится автоматически после завершения.</div></div></div></Transition>

    <Transition name="fade"><div v-if="focusMinimized && !focusOpen && focusedTask" class="focus-mini-window" :class="{'ritual-active':Boolean(ritualTimer.habit)}" role="region" aria-label="Мини-окно режима «Сейчас»"><div class="focus-mini-info"><div class="focus-mini-status"><i :class="{running:focusRunning}"></i>{{focusRunning?'Фокус активен':'Фокус на паузе'}}</div><div class="focus-mini-task"><strong :title="focusedTask.title">{{focusedTask.title}}</strong><small v-if="taskProjectInfo(focusedTask)" :title="`Проект: ${taskProjectInfo(focusedTask).name}`">{{taskProjectInfo(focusedTask).name}}</small></div><span class="focus-mini-time" :aria-label="`Осталось ${timerText(focusSeconds)}`">{{timerText(focusSeconds)}}</span></div><div class="focus-mini-actions"><button type="button" class="focus-mini-button" aria-label="Развернуть режим «Сейчас»" title="Развернуть" @click="restoreFocusMode"><Maximize2 :size="16"/></button><button type="button" class="focus-mini-button" :aria-label="focusRunning?'Приостановить таймер':'Продолжить таймер'" :title="focusRunning?'Пауза':'Продолжить'" @click="toggleFocusTimer"><component :is="focusRunning?Pause:Play" :size="16"/></button><button type="button" class="focus-mini-button finish" aria-label="Завершить задачу" title="Завершить" @click="finishFocusedTask"><Check :size="16"/></button></div></div></Transition>

    <Transition name="fade"><div v-if="cloudOpen" class="modal-backdrop" @click.self="cloudOpen=false"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Единый план на всех устройствах</div><div class="modal-title">Облачная синхронизация</div></div><button class="close" @click="cloudOpen=false"><X :size="17"/></button></div>
      <template v-if="cloud.connected"><div class="card card-pad" style="margin-bottom:16px"><div style="display:flex;align-items:center;gap:12px"><div class="habit-icon" style="background:#13382d;color:#34d399"><Cloud :size="19"/></div><div><strong style="font-size:13px">{{cloud.user?.email}}</strong><div class="habit-sub">Последнее обновление: {{formatSync()}}</div></div></div></div><p class="quote">Изменения сохраняются локально сразу и отправляются в облако при наличии сети. На другом устройстве войдите в этот же аккаунт.</p><div v-if="cloud.error" class="tag" style="color:#fda4af">{{cloud.error}}</div><div class="form-actions"><button class="ghost-btn" @click="signOut"><LogOut :size="15"/> Выйти</button><button class="primary-btn" @click="doSync"><RefreshCw :size="15"/> Обновить сейчас</button></div></template>
      <template v-else><div v-if="!cloud.configured"><p class="quote">Для синхронизации нужен бесплатный проект Supabase. Вставьте URL и публичный anon key. Эти параметры не дают административного доступа к базе.</p><div class="field"><label>Supabase Project URL</label><input class="input" v-model="auth.url" placeholder="https://….supabase.co"/></div><div class="field"><label>Public anon key</label><textarea class="textarea" rows="3" v-model="auth.key" placeholder="eyJ…"></textarea></div><button class="primary-btn" style="width:100%" @click="saveCloudConfig">Сохранить подключение</button></div><div v-else><div class="templates" style="grid-template-columns:1fr 1fr"><button class="template" :style="auth.mode==='signin'?{borderColor:'#7455b5'}:{}" @click="auth.mode='signin'">Войти</button><button class="template" :style="auth.mode==='signup'?{borderColor:'#7455b5'}:{}" @click="auth.mode='signup'">Создать аккаунт</button></div><div class="field"><label>Email</label><input type="email" class="input" v-model="auth.email"/></div><div class="field"><label>Пароль (минимум 6 символов)</label><input type="password" class="input" v-model="auth.password"/></div><div v-if="cloud.error" style="font-size:11px;color:#fb7185;margin-bottom:10px">{{cloud.error}}</div><button class="primary-btn" style="width:100%" :disabled="auth.busy" @click="submitAuth">{{auth.mode==='signin'?'Войти и синхронизировать':'Создать защищённый аккаунт'}}</button></div></template>
    </div></div></Transition>

    <Transition name="fade"><div v-if="ritualTimer.habit" class="ritual-timer-dock"><div><span>{{ritualTimer.habit.title}}</span><strong>{{timerText(ritualTimer.seconds)}}</strong></div><button class="icon-btn" @click="toggleRitualTimer"><component :is="ritualTimer.running?Pause:Play" :size="17"/></button><button class="close" @click="closeRitualTimer"><X :size="15"/></button></div></Transition>

    <Transition name="fade"><div v-if="toast" class="toast" role="status">{{toast}} <button v-if="lastDeleted" @click="undoDelete">Отменить</button><button v-if="updateAvailable" @click="applyUpdate">Обновить</button></div></Transition>
  </div>
</template>
